insert into public.mercury_library (scope, kind, title, description, themes, category, methods, content, draft) values ('mercury', 'goal', 'המבוגר הזמין: ביטחון בשגרה', 'להרגיש שיש מבוגר שאפשר לסמוך עליו שיהיה שם', array['ביטחון ויציבות']::text[], 'ביטחון ויציבות', array['מעגל הביטחון', 'TBRI', 'ARC', 'Theraplay']::text[], '{"v": 2, "bank": 3, "review": 3, "avoid": "לא להבטיח מה שלא בטוח, ולא לחבק בכפייה", "strengths": ["אמון", "פתיחות", "בקשת עזרה", "סקרנות"], "skills": ["פנייה למבוגר"], "main": "2-5", "also": ["6-9"], "evidence": {"level": "derived", "note": "נגזר מגישות התקשרות: מעגל הביטחון נבדק בעיקר עם הורים, ו-ARC ו-TBRI נבדקו גם במסגרות מגורים. התרגום לפעולות יומיומיות של הצוות הוא התאמה שטרם נבדקה כשלעצמה."}, "ages": {"2-5": {"targets": [{"id": "t1", "text": "כשיש הזדמנות בתחילת היום או המשמרת, מגיב/ה לברכה אישית של מבוגר (מבט, קרבה, חיוך או מילה)", "staff": "מגיב/ה כשמברכים אותו/ה בשם", "scale": ["עדיין לא מגיב/ה לברכה", "מגיב/ה לפעמים, אחרי זמן", "מגיב/ה במבט או בחיוך", "ניגש/ת למבוגר שמברך", "מברך/ת בעצמו/ה מבוגרים שונים"]}, {"id": "t2", "text": "ברגעי מצוקה, מקבל/ת נוכחות של מבוגר רגוע במרחק שנוח לו/ה, וסימני המצוקה יורדים בהדרגה", "staff": "כשקשה, מסכים/ה שנשב לידו/ה ונרגע/ת", "scale": ["עדיין מתרחק/ת ממבוגר כשקשה", "מסכים/ה שמבוגר יהיה רחוק", "מסכים/ה שמבוגר יישב קרוב", "נרגע/ת בהדרגה כשמבוגר לידו/ה", "פונה בעצמו/ה למבוגרים שונים כשקשה"]}, {"id": "t3", "text": "כשיש הזדמנות במשחק, משתמש/ת במבוגר מוכר כבסיס בטוח: יוצא/ת לשחק וחוזר/ת אליו", "staff": "יוצא/ת לשחק וחוזר/ת לבדוק שאנחנו כאן", "scale": ["עדיין צמוד/ה או רחוק/ה לגמרי", "משחק/ת רק כשהמבוגר ממש לידו/ה", "משחק/ת קרוב ומסתכל/ת לעבר המבוגר", "יוצא/ת לשחק וחוזר/ת מדי פעם", "משחק/ת בחופשיות, בכל מקום, וחוזר/ת כשצריך"]}, {"id": "t4", "text": "בחילופי משמרת, מקבל/ת את המבוגר של המשמרת הבאה", "staff": "מקבל/ת את המבוגר של המשמרת הבאה", "scale": ["עדיין מתרחק/ת ממבוגר חדש במשמרת", "מקבל/ת אותו אחרי זמן רב", "מקבל/ת אותו בעזרת המבוגר היוצא", "מקבל/ת אותו מהר", "מקבל/ת בקלות מבוגרים שונים"]}, {"id": "t5", "text": "כשיש צורך, מבקש/ת עזרה ממבוגר במילה, בתנועה או בהצבעה", "staff": "מראה או אומר/ת לנו כשצריך עזרה", "scale": ["עדיין לא מבקש/ת עזרה", "מבקש/ת בבכי או בצעקה", "מבקש/ת בתנועה כשהמבוגר שואל", "מבקש/ת בעצמו/ה בתנועה או במילה", "מבקש/ת במילים ממבוגרים שונים"]}], "interventions": [{"id": "i1", "name": "רגע חיבור קבוע", "what": "כמה דקות של משחק או שיחה שהילד/ה מוביל/ה, בגובה העיניים, בשם ובמילים פשוטות.", "why": "רגעים קבועים בונים אמון שהמבוגר יהיה שם.", "freq": "באופן קבוע, בכל משמרת", "approach": "TBRI", "targets": ["t1", "t3"], "sentences": ["עכשיו הזמן שלנו. מה נשחק?", "אני כאן איתך", "בחרת משחק יפה"], "avoid": "לא לבטל את רגע החיבור כעונש"}, {"id": "i2", "name": "ברכה אישית", "what": "בתחילת היום והמשמרת מברכים בשם ובגובה העיניים, ומחכים לתגובה בלי לדרוש אותה.", "why": "הילד/ה לומד/ת שמחכים לו/ה ושמחים לראות אותו/ה.", "freq": "בכל תחילת יום ומשמרת", "approach": "מעגל הביטחון", "targets": ["t1"], "sentences": ["בוקר טוב! איזה כיף לראות אותך", "אני כאן היום עד הערב", "כבר חיכיתי לך"], "avoid": "לא לדרוש תשובה, נשיקה או חיבוק"}, {"id": "i3", "name": "מבוגר שנשאר קרוב", "what": "גם כשהילד/ה כועס/ת או מתרחק/ת, המבוגר נשאר בקרבת מקום ומזמין, בלי ללחוץ.", "why": "הילד/ה לומד/ת שהמבוגר לא נעלם גם כשקשה.", "freq": "ברגעי מצוקה", "approach": "מעגל הביטחון", "targets": ["t2"], "sentences": ["אני נשאר/ת קרוב", "אפשר לבוא אליי כשבא לך", "אני לא הולך/ת"], "avoid": "לא להתרחק כעונש כשהילד/ה כועס/ת"}, {"id": "i4", "name": "העברה חמה בין משמרות", "what": "המבוגר היוצא מציג לילד/ה את המבוגר הנכנס, אומר מה הילד/ה אוהב/ת, ונפרד בקצרה.", "why": "העברה חמה מראה שהשמירה ממשיכה.", "freq": "בכל חילופי משמרת", "approach": "ARC", "targets": ["t4"], "sentences": ["עכשיו המשמרת מתחלפת, ומי שאיתך בערב כבר כאן", "סיפרתי מה הכי כיף לך לשחק", "ביי, נתראה במשמרת הבאה שלי"], "avoid": "לא להיעלם בלי להיפרד, גם כשהילד/ה עסוק/ה"}, {"id": "i5", "name": "עונים לסימנים קטנים", "what": "שמים לב למבט, לתנועה או לבכי קטן, ועונים להם, גם כשהילד/ה לא מבקש/ת במילים.", "why": "כשסימנים קטנים נענים, הילד/ה לומד/ת שרואים אותו/ה.", "freq": "לאורך היום", "approach": "מעגל הביטחון", "targets": ["t5", "t2"], "sentences": ["ראיתי שהסתכלת עליי, אני כאן", "נראה לי שצריך משהו", "בוא/י נראה ביחד"]}, {"id": "i6", "name": "בסיס בטוח במשחק", "what": "יושבים במקום קבוע ליד המשחק, מחייכים כשהילד/ה מסתכל/ת, ומקבלים בחום כשחוזר/ת.", "why": "מי שיודע/ת שיש לאן לחזור, מעז/ה לצאת ולחקור.", "freq": "בזמני משחק", "approach": "מעגל הביטחון", "targets": ["t3"], "sentences": ["אני פה. אפשר ללכת לשחק", "חזרת! ספר/י לי מה עשית", "ראיתי אותך מטפס/ת"], "avoid": "לא לצאת מהחדר בלי להגיד"}, {"id": "i7", "name": "עונים לבקשת עזרה", "what": "כשמבקש/ת עזרה בכל דרך, עונים מהר, אומרים במילים מה הבנו, ומראים איך מבקשים בפעם הבאה.", "why": "בקשה שנענית מלמדת שכדאי לפנות למבוגר.", "freq": "בכל בקשה", "approach": "TBRI", "targets": ["t5"], "sentences": ["ביקשת עזרה, איזה יופי", "בוא/י נעשה את זה יחד", "אפשר להגיד לי: עזרה"], "avoid": "לא להתעלם מבקשה שנאמרה בבכי או בצעקה"}, {"id": "i8", "name": "משחק קצר ושמח (בהשראת Theraplay)", "what": "משחק קצר ומוכר שהמבוגר מוביל, כמו מחיאות כפיים או מחבואים קטנים, עם חיוך. רק אם הילד/ה רוצה. המטפלת מדריכה.", "why": "משחק משותף ושמח בונה קשר וביטחון.", "freq": "באופן קבוע, בזמנים רגועים", "approach": "Theraplay", "targets": ["t1", "t3"], "sentences": ["בוא/י נשחק את המשחק שלנו", "איפה הידיים? הנה הן!", "עוד פעם?"], "avoid": "לא לכפות מגע או מבט בעיניים"}]}}}'::jsonb, true) on conflict (scope, institution, kind, title) do update set description = excluded.description, themes = excluded.themes, category = excluded.category, methods = excluded.methods, content = excluded.content, active = true where mercury_library.draft;
insert into public.mercury_library (scope, kind, title, description, themes, category, methods, content, draft) values ('mercury', 'goal', 'יום שיודעים מה יהיה בו', 'להרגיש בטוח כשהיום צפוי ומוכר', array['ביטחון ויציבות']::text[], 'ביטחון ויציבות', array['ARC', 'NMT', 'ויסות חושי', 'TBRI', 'מעגל הביטחון']::text[], '{"v": 2, "bank": 3, "review": 3, "avoid": "לא להפתיע בשינויים כשאפשר להכין", "strengths": ["סקרנות", "שיתוף פעולה", "סבלנות"], "skills": ["מעבר בין פעילויות"], "main": "2-5", "also": ["6-9"], "evidence": {"level": "derived", "note": "שגרה צפויה היא עיקרון מרכזי ב-ARC ובמודלים למסגרות מגורים (CARE), ונחשבת לפרקטיקה מקובלת בגיל הרך. לוח יום בתמונות כפעולת צוות טרם נבדק כשלעצמו."}, "ages": {"2-5": {"targets": [{"id": "t1", "text": "כשיש הזדמנות במעבר בין פעילויות, עובר/ת לפעילות הבאה בעזרת תמונה או משפט קבוע", "staff": "עובר/ת לדבר הבא בעזרת התמונה", "scale": ["עדיין מתקשה מאוד בכל מעבר", "עובר/ת בליווי צמוד", "עובר/ת עם תמונה ועזרה", "עובר/ת עם תמונה בלבד", "עובר/ת בעצמו/ה, גם עם מבוגרים שונים"]}, {"id": "t2", "text": "בתחילת היום מסתכל/ת עם מבוגר על לוח היום בתמונות", "staff": "מסתכל/ת איתנו בבוקר על לוח היום", "scale": ["עדיין לא מתעניין/ת בלוח", "מסתכל/ת רגע כשמראים", "מצביע/ה על תמונה אחת", "אומר/ת מה בא אחר כך", "ניגש/ת ללוח בעצמו/ה, גם עם מבוגרים שונים"]}, {"id": "t3", "text": "כשיש שינוי לא צפוי, מקבל/ת הסבר קצר ונרגע/ת בעזרת מבוגר", "staff": "נרגע/ת אחרי הסבר כשמשהו משתנה", "scale": ["עדיין מתקשה מאוד בכל שינוי", "נרגע/ת אחרי זמן רב", "נרגע/ת עם הסבר וקרבה של מבוגר", "נרגע/ת עם הסבר קצר", "שואל/ת בעצמו/ה מה משתנה"]}, {"id": "t4", "text": "בשעת השינה משתף/ת פעולה עם טקס ערב קבוע", "staff": "נכנס/ת למיטה בעזרת טקס הערב", "scale": ["עדיין מתקשה מאוד בכל ערב", "נרדם/ת עם מבוגר צמוד לאורך זמן", "משתף/ת פעולה עם חלק מהטקס", "עובר/ת את הטקס בעזרה קלה", "מזכיר/ה בעצמו/ה מה בא בטקס, עם כל מבוגר"]}, {"id": "t5", "text": "כשיש הזדמנות, אומר/ת או מראה מי המבוגר שאיתו/ה עכשיו", "staff": "יודע/ת מי איתו/ה במשמרת", "scale": ["עדיין לא מזהה את המבוגרים", "מזהה מבוגר אחד מוכר", "מצביע/ה כששואלים", "אומר/ת את השם כששואלים", "מחפש/ת בעצמו/ה את המבוגר של המשמרת"]}], "interventions": [{"id": "i1", "name": "לוח יום בתמונות", "what": "לוח בגובה העיניים עם כמה תמונות של היום. בבוקר עוברים עליו יחד, ומזיזים סימן אחרי כל פעילות.", "why": "כשרואים מה יהיה, הגוף נרגע.", "freq": "כל יום", "approach": "ARC", "targets": ["t2", "t1"], "sentences": ["בוא/י נראה מה יש לנו היום", "עכשיו ארוחה, ואחר כך גינה", "את זה כבר עשינו, נזיז את הסימן"], "avoid": "לא לשנות את הלוח כל יום מחדש"}, {"id": "i2", "name": "משפט מעבר קבוע", "what": "לפני כל מעבר אותו משפט, ומראים את התמונה הבאה.", "why": "משפט קבוע הופך מעבר לצפוי.", "freq": "לפני מעברים", "approach": "ARC", "targets": ["t1"], "sentences": ["עוד מעט נגמר, ואחר כך מקלחת", "קודם מקלחת, ואחר כך סיפור", "בוא/י נראה בלוח מה עכשיו"]}, {"id": "i3", "name": "הכנה לשינוי", "what": "כשמשהו משתנה, מסבירים במשפט אחד ומראים בתמונה, עדיף לפני שזה קורה.", "why": "שינוי שמוסבר מראש מפחיד פחות.", "freq": "כשיש שינוי", "approach": "TBRI", "targets": ["t3"], "sentences": ["היום יש שינוי קטן, ואני אסביר לך", "אני איתך גם בשינוי", "אחרי זה חוזרים לרגיל"], "avoid": "לא להסתיר שינוי עד הרגע האחרון"}, {"id": "i4", "name": "טקס ערב קבוע", "what": "אותו סדר בכל ערב: מקלחת, פיג׳מה, סיפור, שיר ומילה טובה, ואור קטן.", "why": "טקס חוזר מאותת לגוף שבטוח להירדם.", "freq": "כל ערב", "approach": "NMT", "targets": ["t4"], "sentences": ["עכשיו השיר שלנו, ואז לילה טוב", "ואני בודק/ת שוב בעוד רגע", "בבוקר יחכה לך כאן מבוגר מהצוות"]}, {"id": "i5", "name": "מי איתי היום", "what": "בתחילת משמרת המבוגר מציג את עצמו, ותמונות המבוגרים של היום תלויות על הלוח.", "why": "לדעת מי שומר עליי זה הבסיס לביטחון.", "freq": "בכל תחילת משמרת", "approach": "מעגל הביטחון", "targets": ["t5"], "sentences": ["היום אני איתך עד הערב", "הנה התמונות של מי איתך היום", "בלילה יש מדריך ער ששומר עליך"]}, {"id": "i6", "name": "פחות הפתעות לחושים", "what": "מורידים רעש ואור בזמני מעבר, ומודיעים לפני רעש צפוי.", "why": "רעש ואור פתאומיים מבהילים ילדים שעברו הרבה.", "freq": "לאורך היום", "approach": "ויסות חושי", "targets": ["t3", "t1"], "sentences": ["עוד רגע יהיה רעש של שואב, זה בסדר", "בוא/י נשב רגע בפינת ההרגעה", "נכבה קצת את האור"]}, {"id": "i7", "name": "תשובה כנה ל׳מתי׳", "what": "כששואל/ת מה יהיה או מתי, עונים בכנות ובפשטות ומראים על הלוח. כשלא יודעים, אומרים שלא יודעים.", "why": "תשובה כנה בונה אמון יותר מהבטחה.", "freq": "בכל שאלה", "approach": "TBRI", "targets": ["t2", "t3"], "sentences": ["אני לא יודע/ת עדיין, ואספר לך כשאדע", "בוא/י נראה בלוח", "אחרי השינה, זה מה שיהיה"], "avoid": "לא להבטיח מה שלא בטוח"}, {"id": "i8", "name": "מקום קבוע משלו/ה", "what": "מקום קבוע לחפצים של הילד/ה, שהצוות שומר עליו.", "why": "משהו קבוע שלי בתוך מקום חדש נותן שייכות.", "freq": "תמיד", "approach": "ARC", "targets": ["t3", "t4"], "sentences": ["זו הקופסה שלך, ואנחנו שומרים עליה", "הדברים שלך מחכים לך כאן", "רוצה לשים משהו בקופסה?"]}]}}}'::jsonb, true) on conflict (scope, institution, kind, title) do update set description = excluded.description, themes = excluded.themes, category = excluded.category, methods = excluded.methods, content = excluded.content, active = true where mercury_library.draft;
insert into public.mercury_library (scope, kind, title, description, themes, category, methods, content, draft) values ('mercury', 'goal', 'להרגיש בטוח במקום חדש', 'להכיר את המקום ואת האנשים ולהתחיל להרגיש בו בטוח', array['ביטחון ויציבות']::text[], 'ביטחון ויציבות', array['TBRI', 'ARC', 'מעגל הביטחון', 'DDP/PACE', 'NMT']::text[], '{"v": 2, "bank": 3, "review": 1, "avoid": "לא להעמיס הרבה כללים ופנים חדשות ביום הראשון", "strengths": ["אומץ", "סקרנות", "פתיחות", "שיתוף פעולה"], "skills": ["פנייה למבוגר"], "main": "6-9", "also": ["10-12"], "evidence": {"level": "derived", "note": "נגזר מעקרונות הטיפול מותאם הטראומה (בטחה, צפיות, בחירה) ומ-ARC. מרכזי חירום הם שלב משבר עם שהייה קצרה; פעולות הקליטה המוצעות כאן הן התאמה יישומית שטרם נבדקה."}, "ages": {"6-9": {"targets": [{"id": "t1", "text": "בימים הראשונים, יודע/ת למי לפנות ואיפה הדברים שלו/ה", "staff": "יודע/ת למי לפנות ואיפה הדברים", "scale": ["עדיין מבולבל/ת ולא פונה לאיש", "פונה כשמבוגר ניגש", "יודע/ת איפה החדר והדברים", "פונה למבוגר מוכר כשצריך", "מתמצא/ת ופונה למבוגרים שונים"]}, {"id": "t2", "text": "כשיש הזדמנות, משתף/ת מבוגר בפחד או בדאגה לגבי המקום או המשפחה", "staff": "מספר/ת לנו ממה דואג/ת", "scale": ["עדיין שומר/ת הכל בפנים", "מראה דאגה בהתנהגות", "עונה כששואלים", "משתף/ת מבוגר מוכר מיוזמתו/ה", "משתף/ת ושואל/ת, גם מבוגרים שונים"]}, {"id": "t3", "text": "ישן/ה בלילה בלי התעוררויות ארוכות של פחד", "staff": "ישן/ה, ונרגע/ת מהר אם מתעורר/ת", "scale": ["עדיין מתעורר/ת בפחד ברוב הלילות", "נרגע/ת רק עם מבוגר לאורך זמן", "נרגע/ת עם מבוגר מהר", "מתעורר/ת לפעמים ונרגע/ת לבד", "ישן/ה ברצף ברוב הלילות"]}, {"id": "t4", "text": "משתתף/ת בפעילויות הקבוצה ולא נשאר/ת בצד כל הזמן", "staff": "מצטרף/ת לפעילויות של הקבוצה", "scale": ["עדיין נשאר/ת לבד בצד", "מסתכל/ת מהצד", "מצטרף/ת עם מבוגר לידו/ה", "מצטרף/ת לבד לחלק מהפעילויות", "משתתף/ת ברוב הפעילויות, גם בחדשות"]}, {"id": "t5", "text": "שואל/ת על מה שיקרה לו/ה ומקשיב/ה לתשובה", "staff": "שואל/ת מה יקרה ומקשיב/ה לתשובה", "scale": ["עדיין לא שואל/ת", "שואל/ת שוב ושוב בחרדה", "שואל/ת ונרגע/ת לרגע", "שואל/ת ומקבל/ת את התשובה", "מבין/ה מה ידוע ומה עוד לא"]}], "interventions": [{"id": "i1", "name": "סיור היכרות", "what": "ביום הראשון מבוגר אחד עושה איתו/ה סיור: החדר, השירותים, האוכל, ולמי פונים בלילה.", "why": "כשמכירים את המקום, מפחדים פחות.", "freq": "ביום הראשון, ושוב לפי הצורך", "approach": "TBRI", "targets": ["t1"], "sentences": ["בוא/י נראה ביחד איפה הכל", "בלילה יש מדריך ער, ואפשר לקרוא לו", "מה עוד חשוב לך לראות?"]}, {"id": "i2", "name": "מבוגר מלווה בהתחלה", "what": "מבוגר קבוע, כשאפשר, שבודק מה שלומו/ה כמה פעמים ביום בשבוע הראשון.", "why": "קשר אחד יציב מקל על הימים הראשונים.", "freq": "בימים הראשונים", "approach": "מעגל הביטחון", "targets": ["t1", "t2"], "sentences": ["באתי לשאול מה שלומך", "אני כאן גם מחר", "אם משהו מטריד, אפשר לבוא אליי"]}, {"id": "i3", "name": "תשובות כנות ופשוטות", "what": "על שאלות על המשפחה וההמשך עונים בכנות ובפשטות, בלי פרטים מפחידים. מה שלא ידוע אומרים שלא ידוע.", "why": "אמת שמותאמת לגיל מרגיעה יותר משתיקה.", "freq": "בכל שאלה", "approach": "TBRI", "targets": ["t5", "t2"], "sentences": ["זו שאלה חשובה", "את זה עוד לא יודעים. כשיהיה אפשר, צוות הטיפול ידבר איתך על זה", "אני לא יודע/ת, ואבדוק בשבילך"], "avoid": "לא להבטיח מתי חוזרים הביתה"}, {"id": "i4", "name": "טקס לילה בטוח", "what": "לפני השינה בודקים יחד שהחפץ האהוב והאור במקום, ואומרים מי ער בלילה.", "why": "ידיעה מי שומר בלילה מאפשרת להירדם.", "freq": "כל ערב", "approach": "NMT", "targets": ["t3"], "sentences": ["הלילה שומרים עליך", "אם תתעורר/י, אפשר לקרוא לנו", "האור הקטן נשאר דולק"]}, {"id": "i5", "name": "פתח לפחדים", "what": "רגע שקט לשאלה פתוחה: מה הכי קשה כאן? מקשיבים ולא ממהרים לתקן.", "why": "פחד שנאמר בקול נעשה קטן יותר.", "freq": "באופן קבוע", "approach": "DDP/PACE", "targets": ["t2"], "sentences": ["מה היה הכי קשה היום?", "הגיוני שזה מפחיד", "תודה שסיפרת לי"], "avoid": "לא לומר שאין ממה לפחד"}, {"id": "i6", "name": "הצטרפות בהדרגה", "what": "מזמינים לפעילות עם תפקיד קטן, ומאפשרים לצפות קודם.", "why": "הצטרפות הדרגתית שומרת על תחושת שליטה.", "freq": "בפעילויות קבוצתיות", "approach": "ARC", "targets": ["t4"], "sentences": ["רוצה לעזור לי לחלק?", "אפשר להסתכל קודם ולהצטרף אחר כך", "שמרתי לך מקום"]}, {"id": "i7", "name": "חפץ מהבית", "what": "מעודדים לשמור חפץ מוכר מהבית ליד המיטה, ושומרים עליו.", "why": "חפץ מוכר מחבר בין הבית הישן למקום החדש.", "freq": "תמיד", "approach": "מעגל הביטחון", "targets": ["t3", "t1"], "sentences": ["איפה נשים את הדבר שלך?", "הוא נשאר כאן איתך", "נשמור עליו יחד"]}, {"id": "i8", "name": "כללים בהדרגה", "what": "את כללי המקום מסבירים בהדרגה ועם דוגמה, ולא כרשימת איסורים ביום הראשון.", "why": "כללים ברורים נותנים ביטחון כשהם לא מאיימים.", "freq": "בימים הראשונים", "approach": "ARC", "targets": ["t1", "t5"], "sentences": ["כאן אצלנו עושים ככה, ואני אראה לך", "מה עוד לא ברור?", "בהתחלה כולם מתבלבלים, וזה בסדר"]}]}}}'::jsonb, true) on conflict (scope, institution, kind, title) do update set description = excluded.description, themes = excluded.themes, category = excluded.category, methods = excluded.methods, content = excluded.content, active = true where mercury_library.draft;
insert into public.mercury_library (scope, kind, title, description, themes, category, methods, content, draft) values ('mercury', 'goal', 'לבקש עזרה ולקבל אותה', 'לפנות למבוגר כשקשה ולתת לו לעזור', array['ביטחון ויציבות']::text[], 'ביטחון ויציבות', array['CPS', 'TBRI', 'ARC', 'מעגל הביטחון', 'DDP/PACE']::text[], '{"v": 2, "bank": 3, "review": 3, "avoid": "לא לשלוח להסתדר לבד בפעמים הראשונות", "strengths": ["פתיחות", "אומץ", "התמדה", "אמון"], "skills": ["בקשת עזרה"], "main": "6-9", "also": ["10-12"], "evidence": {"level": "derived", "note": "נשען על ARC (התקשרות ומסוגלות), TBRI ו-CPS, שנבדקו במסגרות לילדים. משפט בקשה קבוע ותרגול במשחק הם התאמה יישומית שטרם נבדקה כשלעצמה."}, "ages": {"6-9": {"targets": [{"id": "t1", "text": "כשיש קושי במשימה או עם ילדים, פונה למבוגר במילים", "staff": "פונה אלינו במילים כשקשה", "scale": ["עדיין מוותר/ת או מתפרץ/ת", "פונה בבכי או בכעס", "פונה כשמבוגר שואל", "פונה בעצמו/ה במילים לפעמים", "פונה במילים ברוב הפעמים"]}, {"id": "t2", "text": "כשמבוגר מציע עזרה, מקבל/ת אותה", "staff": "מסכים/ה שנעזור לו/ה", "scale": ["עדיין דוחה עזרה", "מקבל/ת אחרי ויכוח", "מקבל/ת ממבוגר אחד מוכר", "מקבל/ת מרוב המבוגרים", "מבקש/ת ומקבל/ת בנינוחות"]}, {"id": "t3", "text": "פונה ליותר ממבוגר אחד בצוות", "staff": "פונה גם לאנשי צוות אחרים", "scale": ["עדיין פונה לאדם אחד או לאף אחד", "פונה לשניים מוכרים", "פונה לרוב הצוות הקבוע", "פונה גם למבוגר חדש", "בוחר/ת למי לפנות לפי הצורך"]}, {"id": "t4", "text": "אחרי שקיבל/ה עזרה, ממשיך/ה במשימה", "staff": "ממשיך/ה לבד אחרי שעזרנו", "scale": ["עדיין עוזב/ת את המשימה", "ממשיך/ה עם מבוגר צמוד", "ממשיך/ה עם בדיקה מדי פעם", "ממשיך/ה לבד אחרי עזרה קצרה", "מסיים/ת ומספר/ת מה הצליח"]}, {"id": "t5", "text": "אומר/ת כשמשהו מפריע לו/ה או פוגע בו/ה", "staff": "מספר/ת לנו כשמשהו פוגע בו/ה", "scale": ["עדיין שותק/ת או מגיב/ה בכעס", "מספר/ת אחרי שמגלים", "מספר/ת כששואלים", "מספר/ת בעצמו/ה אחרי זמן", "מספר/ת בזמן ומבקש/ת עזרה"]}], "interventions": [{"id": "i1", "name": "משפט בקשה קבוע", "what": "מלמדים משפט אחד לבקשת עזרה במשימה או מול ילד אחר, תולים אותו על כרטיס ומתרגלים ברגעי רוגע.", "why": "משפט מוכן קל יותר להגיד ברגע קשה.", "freq": "באופן קבוע", "approach": "CPS", "targets": ["t1"], "sentences": ["אפשר להגיד: עזרה, בבקשה", "תגיד/י לי מה תקוע", "בוא/י נתרגל את המשפט שלך"]}, {"id": "i2", "name": "מגיבים מהר ובחום", "what": "כל פנייה במילים זוכה לתגובה מהירה, גם אם קצרה.", "why": "כשבקשה נענית, לומדים שכדאי לבקש.", "freq": "בכל פנייה", "approach": "TBRI", "targets": ["t1", "t2"], "sentences": ["אני בא/ה, רגע אחד", "שמעתי אותך, אני מגיע/ה", "בוא/י נראה מה תקוע"]}, {"id": "i3", "name": "עזרה קטנה ולא במקום", "what": "עוזרים בצעד הבא בלבד, ומחזירים את ההובלה לילד/ה.", "why": "עזרה קטנה מלמדת שאפשר להצליח לבד.", "freq": "בכל עזרה", "approach": "ARC", "targets": ["t4", "t2"], "sentences": ["בוא/י נעשה רק את הצעד הראשון ביחד", "עכשיו תמשיך/י, ואני פה", "ראיתי שהצלחת להמשיך לבד"], "avoid": "לא לעשות את כל המשימה במקומו/ה"}, {"id": "i4", "name": "מכירים את כל הצוות", "what": "מציגים את אנשי הצוות בשמות ובתמונות, ומזמינים לבקש משהו קטן ממבוגר אחר.", "why": "ביטחון רחב לא תלוי באדם אחד.", "freq": "באופן קבוע", "approach": "מעגל הביטחון", "targets": ["t3"], "sentences": ["בוא/י נבקש ביחד מהמדריך של הערב", "גם הוא יכול לעזור לך", "מי עוד יכול לעזור כאן?"]}, {"id": "i5", "name": "תגובה רגועה לשיתוף", "what": "כשמספר/ת שמשהו פגע בו/ה, קודם מודים ומקשיבים עד הסוף, בלי שאלות מכוונות. אם מדובר בפגיעה, אומרים בכנות שמספרים למטפלת כדי לעזור.", "why": "תגובה רגועה מלמדת שבטוח לספר.", "freq": "בכל שיתוף", "approach": "DDP/PACE", "targets": ["t5"], "sentences": ["תודה שסיפרת לי", "זה לא בסדר שזה קרה לך", "אני מספר/ת למטפלת, כדי שנוכל לעזור לך"], "avoid": "לא לחקור ולא לשאול שאלות מכוונות על מה שקרה. מעבירים למטפלת"}, {"id": "i6", "name": "משחק בקשות", "what": "משחקי תפקידים קצרים בזמן רגוע: בובה או ילד/ה מבקש/ת עזרה ממבוגר.", "why": "תרגול ברוגע מכין לרגע הקשה.", "freq": "מדי פעם, בזמן רגוע", "approach": "CPS", "targets": ["t1", "t3"], "sentences": ["בוא/י נשחק שהבובה צריכה עזרה", "איך היא יכולה לבקש?", "עכשיו תורך לבקש"]}, {"id": "i7", "name": "שבח על הבקשה", "what": "משבחים את האומץ לבקש, בתיאור מדויק, ולא רק את התוצאה.", "why": "שבח על הדרך מחזק את מה שרוצים שיחזור.", "freq": "בכל בקשה", "approach": "TBRI", "targets": ["t1", "t5"], "sentences": ["ביקשת עזרה כשהיה קשה, זה אומץ", "ראיתי שפנית אליי במילים", "ככה בדיוק עושים"]}, {"id": "i8", "name": "גם הילד/ה עוזר/ת", "what": "נותנים לילד/ה לעזור למבוגר או לילד אחר במשימה קטנה.", "why": "מי שעוזר/ת לאחרים חווה שעזרה היא דבר טבעי.", "freq": "מדי פעם", "approach": "ARC", "targets": ["t2", "t4"], "sentences": ["אני צריך/ה את העזרה שלך עכשיו", "תודה, עזרת לי מאוד", "גם אני צריך/ה לפעמים עזרה"]}]}}}'::jsonb, true) on conflict (scope, institution, kind, title) do update set description = excluded.description, themes = excluded.themes, category = excluded.category, methods = excluded.methods, content = excluded.content, active = true where mercury_library.draft;
insert into public.mercury_library (scope, kind, title, description, themes, category, methods, content, draft) values ('mercury', 'goal', 'מבוגר אחד משמעותי', 'לבנות קשר יציב ועמוק עם מבוגר אחד בצוות', array['ביטחון ויציבות']::text[], 'ביטחון ויציבות', array['ARC', 'TBRI', 'DDP/PACE', 'סמכות חדשה', 'CPS', 'מעגל הביטחון']::text[], '{"v": 2, "bank": 3, "review": 3, "avoid": "לא להעניש בניתוק או בביטול הזמן הקבוע", "strengths": ["אמון", "כנות", "פתיחות", "אחריות"], "skills": ["שיתוף רגשות"], "main": "10-12", "also": [], "evidence": {"level": "derived", "note": "קשר עם מבוגר יציב הוא גורם מגן מבוסס, ועומד בבסיס ARC, TBRI ו-CARE במסגרות מגורים. מבנה של מבוגר משמעותי וזמן קבוע שבועי הוא התאמה יישומית."}, "ages": {"10-12": {"targets": [{"id": "t1", "text": "כשיש הזדמנות, יוזם/ת שיחה או פעילות עם המבוגר המשמעותי", "staff": "בא/ה אלינו לדבר או לעשות משהו יחד", "scale": ["עדיין שומר/ת מרחק", "מגיב/ה בקצרה כשפונים", "משתתף/ת בזמן הקבוע", "יוזם/ת מדי פעם", "יוזם/ת ומשתף/ת בדברים אישיים"]}, {"id": "t2", "text": "משתף/ת את המבוגר בדבר שחשוב לו/ה", "staff": "מספר/ת לנו דברים שחשובים לו/ה", "scale": ["עדיין לא משתף/ת", "משתף/ת רק עובדות", "משתף/ת רגש כששואלים", "משתף/ת מיוזמתו/ה לפעמים", "משתף/ת ומבקש/ת עצה"]}, {"id": "t3", "text": "חוזר/ת לקשר אחרי ריב או אכזבה", "staff": "חוזר/ת אלינו אחרי שכעס/ה", "scale": ["עדיין מתרחק/ת לימים", "חוזר/ת כשמבוגר מתקן", "חוזר/ת אחרי שיחה", "חוזר/ת בעצמו/ה תוך יום", "מדבר/ת על מה שקרה וממשיך/ה"]}, {"id": "t4", "text": "מגיע/ה לזמן הקבוע עם המבוגר", "staff": "מגיע/ה לזמן הקבוע שלנו", "scale": ["עדיין לא מגיע/ה", "מגיע/ה כשמזכירים", "מגיע/ה לרוב הפעמים", "מגיע/ה ומחכה לזמן הזה", "מתכנן/ת איתנו מה נעשה"]}, {"id": "t5", "text": "מקבל/ת עצה או גבול מהמבוגר בלי לנתק את הקשר, גם עם מבוגרים אחרים", "staff": "מקשיב/ה גם כשאומרים לא", "scale": ["עדיין מגיב/ה בכעס ומתרחק/ת", "מקבל/ת אחרי ויכוח ארוך", "מקבל/ת ומתלונן/ת", "מקבל/ת ומבקש/ת הסבר", "מקבל/ת ומציע/ה פתרון, גם מול מבוגרים אחרים"]}], "interventions": [{"id": "i1", "name": "בוחרים מבוגר משמעותי", "what": "הצוות בוחר יחד עם הילד/ה מבוגר אחד לתקופה, כשאפשר לפי בחירתו/ה.", "why": "קשר עמוק אחד מגן מאוד.", "freq": "בתחילת התקופה, ובדיקה מדי פעם", "approach": "ARC", "targets": ["t1", "t4"], "sentences": ["עם מי מהצוות נוח לך לדבר?", "אני כאן בשבילך בתקופה הזאת", "נבדוק יחד מדי פעם איך זה"]}, {"id": "i2", "name": "זמן קבוע", "what": "זמן קבוע באותה שעה לפעילות שהילד/ה בוחר/ת: הליכה, משחק, בישול.", "why": "זמן צפוי ומשותף בונה אמון.", "freq": "באופן קבוע", "approach": "TBRI", "targets": ["t4", "t1"], "sentences": ["מה בא לך לעשות היום בזמן שלנו?", "אני מחכה לזמן הזה", "בפעם הבאה תורך לבחור"]}, {"id": "i3", "name": "סקרנות בלי חקירה", "what": "שואלים מתוך עניין, ומקבלים גם תשובות קצרות בלי לדחוק.", "why": "כשלא לוחצים, קל יותר לספר.", "freq": "בכל מפגש", "approach": "DDP/PACE", "targets": ["t2"], "sentences": ["ספר/י לי עוד, אם בא לך", "מעניין אותי מה חשבת על זה", "לא חייבים לענות"]}, {"id": "i4", "name": "תיקון אחרי ריב", "what": "אחרי עימות המבוגר יוזם תיקון: מכיר בחלק שלו, ושואל מה היה קשה.", "why": "תיקון מלמד שקשר יכול לשרוד כעס.", "freq": "אחרי עימות", "approach": "DDP/PACE", "targets": ["t3"], "sentences": ["הייתי קשה איתך קודם, ואני רוצה לתקן", "אני עדיין כאן, גם אחרי הריב", "מה היה הכי קשה לך?"], "avoid": "לא לדרוש התנצלות מהילד/ה כתנאי לתיקון"}, {"id": "i5", "name": "גבול עם הסבר", "what": "כשאומרים לא, מסבירים בקצרה למה ומציעים מה כן אפשר.", "why": "גבול עם הסבר שומר על הקשר ועל הכבוד.", "freq": "בכל גבול", "approach": "סמכות חדשה", "targets": ["t5"], "sentences": ["לא, כי זה לא בטוח. מה שכן אפשר זה...", "אני אומר/ת לא, ואני עדיין בצד שלך", "בוא/י נחפש דרך אחרת"]}, {"id": "i6", "name": "פתק קטן", "what": "המבוגר משאיר פתק קצר, חם וגלוי, לפי נוהל המרכז, למשל לפני חופש או אחרי יום קשה.", "why": "קשר נמשך גם כשהמבוגר לא נמצא.", "freq": "מדי פעם", "approach": "מעגל הביטחון", "targets": ["t1", "t3"], "sentences": ["כתבתי לך משהו קטן", "חשבתי עליך כשלא הייתי פה", "אפשר לענות לי, אם בא לך"]}, {"id": "i7", "name": "פרידה מתוכננת", "what": "כשהמבוגר יוצא לחופש או עוזב, או כשהילד/ה עובר/ת למקום אחר, מודיעים מראש ומסכמים איך נפרדים ומי ממשיך.", "why": "פרידה מתוכננת לא חוזרת על חוויית נטישה.", "freq": "לפני היעדרות", "approach": "ARC", "targets": ["t3", "t4"], "sentences": ["בעוד שבוע אני יוצא/ת לחופש", "מי ישמור איתך על קשר בינתיים?", "כשאחזור, נמשיך מאיפה שעצרנו"], "avoid": "לא להיעלם בלי פרידה"}, {"id": "i8", "name": "קול בהחלטות", "what": "מערבים את הילד/ה בהחלטות קטנות שנוגעות לו/ה.", "why": "כששומעים את דעתו/ה, הוא/היא מרגיש/ה חשוב/ה.", "freq": "כשיש החלטה", "approach": "CPS", "targets": ["t5", "t2"], "sentences": ["מה דעתך? יש שתי אפשרויות", "בוא/י נחליט ביחד", "הדעה שלך חשובה פה"]}]}}}'::jsonb, true) on conflict (scope, institution, kind, title) do update set description = excluded.description, themes = excluded.themes, category = excluded.category, methods = excluded.methods, content = excluded.content, active = true where mercury_library.draft;
insert into public.mercury_library (scope, kind, title, description, themes, category, methods, content, draft) values ('mercury', 'goal', 'אמון מחדש: קשר ששורד כעס', 'לגלות שאפשר לסמוך על מבוגרים גם אחרי פגיעה ועימות', array['ביטחון ויציבות']::text[], 'ביטחון ויציבות', array['סמכות חדשה', 'DDP/PACE', 'CPS', 'TF-CBT', 'ARC']::text[], '{"v": 2, "bank": 3, "review": 3, "avoid": "לא להיגרר לוויכוח בזמן סערה, ולא להשפיל מול הקבוצה", "strengths": ["כנות", "אחריות", "עמידות", "מנהיגות"], "skills": ["פתרון בעיות בשיחה"], "main": "13-15", "also": [], "evidence": {"level": "derived", "note": "נשען על DDP/PACE, סמכות חדשה (NVR) ו-CPS. הראיות למתבגרים במסגרות מגורים מוגבלות; העקרונות של תיקון, נוכחות ודחיית תגובה מבוססים, והתרגום לשגרת צוות הוא התאמה יישומית."}, "ages": {"13-15": {"targets": [{"id": "t1", "text": "כשיש הזדמנות, מדבר/ת עם מבוגר בצוות על מה שחשוב לו/ה", "staff": "מדבר/ת איתנו על מה שחשוב לו/ה", "scale": ["עדיין נמנע/ת משיחה", "מדבר/ת רק על עניינים טכניים", "מדבר/ת כשמבוגר יוזם", "יוזם/ת שיחה לפעמים", "מתייעץ/ת עם מבוגרים שונים"]}, {"id": "t2", "text": "אחרי פיצוץ, חוזר/ת לשיחה עם המבוגר תוך זמן סביר", "staff": "חוזר/ת לדבר איתנו אחרי שכעס/ה", "scale": ["עדיין מתרחק/ת לימים", "חוזר/ת אחרי שמבוגר פונה שוב", "חוזר/ת אחרי יום", "חוזר/ת תוך שעות", "מדבר/ת על מה שקרה ומתקן/ת"]}, {"id": "t3", "text": "מקבל/ת גבול בלי לראות בו סוף של הקשר", "staff": "מבין/ה שגבול הוא לא סוף הקשר", "scale": ["עדיין חווה כל גבול כדחייה", "מקבל/ת גבול ומתרחק/ת", "מקבל/ת גבול וכועס/ת זמן קצר", "מקבל/ת גבול ומדבר/ת עליו", "מבין/ה ומציע/ה פשרה"]}, {"id": "t4", "text": "עומד/ת בהסכם קטן עם המבוגר", "staff": "עומד/ת במה שסיכמנו", "scale": ["עדיין לא עומד/ת בהסכמים", "עומד/ת עם תזכורות רבות", "עומד/ת בחלק מההסכמים", "עומד/ת ברוב ההסכמים", "מציע/ה הסכמים בעצמו/ה, גם מול מבוגרים אחרים"]}, {"id": "t5", "text": "מביע/ה כעס במילים ולא בפגיעה", "staff": "אומר/ת במילים שכועס/ת", "scale": ["עדיין פוגע/ת או הורס/ת", "צועק/ת ומעליב/ה", "צועק/ת בלי להעליב", "אומר/ת בטון חזק שכועס/ת", "אומר/ת מה מכעיס ומה צריך"]}], "interventions": [{"id": "i1", "name": "נוכחות שלא נשברת", "what": "גם אחרי התנהגות קשה המבוגר חוזר לקשר: שלום, הצעה לשיחה, בלי טינה.", "why": "מי שנפגע/ה בודק/ת שוב ושוב אם המבוגר ייעלם.", "freq": "אחרי כל אירוע", "approach": "סמכות חדשה", "targets": ["t2", "t1"], "sentences": ["אני לא הולך/ת לשום מקום", "אני עדיין כאן, גם כשקשה", "נדבר כשתרגיש/י מוכן/ה"], "avoid": "לא להעניש בשתיקה או בניתוק"}, {"id": "i2", "name": "שיחה בפרטיות", "what": "שיחות רגישות בפרטיות, בהליכה או ליד שולחן, לא מול הקבוצה.", "why": "שיחה בפרטיות מפחיתה בושה.", "freq": "בשיחות רגישות", "approach": "DDP/PACE", "targets": ["t1"], "sentences": ["בוא/י נדבר רגע בחוץ", "זה לא יגיע לקבוצה. מה שחשוב כדי לעזור לך, אני משתף/ת עם המטפלת", "אפשר לעצור מתי שרוצים"]}, {"id": "i3", "name": "חוזרים לשיחה אחרי סערה", "what": "אחרי שהסערה נרגעה, המבוגר חוזר לנושא בשקט ובפרטיות, ומחפשים יחד מה לתקן.", "why": "חזרה רגועה מלמדת שאפשר לדבר גם על דברים קשים.", "freq": "אחרי סערה, כשרגוע", "approach": "CPS", "targets": ["t2", "t5"], "sentences": ["אני רוצה לחזור למה שקרה קודם", "מה היה הכי קשה לך?", "מה אפשר לתקן עכשיו?"]}, {"id": "i4", "name": "הסכם קטן וברור", "what": "מסכמים יחד הסכם קטן לתקופה קצרה, כותבים אותו ובודקים יחד בסוף.", "why": "הצלחה בהסכם קטן בונה אמון הדדי.", "freq": "באופן קבוע", "approach": "CPS", "targets": ["t4"], "sentences": ["על מה נסכם השבוע?", "איך הלך לנו ההסכם?", "מה צריך לשנות כדי שיעבוד?"]}, {"id": "i5", "name": "גבול מכבד", "what": "גבול נאמר ברוגע, עם סיבה ועם מה כן אפשר, והמבוגר מכיר ברגש.", "why": "גבול מכבד לא נחווה כדחייה.", "freq": "בכל גבול", "approach": "DDP/PACE", "targets": ["t3"], "sentences": ["אני מבין/ה שזה מעצבן, והתשובה עדיין לא", "מה כן יכול לעבוד בשבילך?", "הגבול לא משנה את היחס שלי אליך"]}, {"id": "i6", "name": "מילים לכעס (בהשראת TF-CBT)", "what": "בזמן רגוע עוזרים למצוא מילים לכעס, ותוכנית למה עושים כשהוא עולה. המטפלת מדריכה.", "why": "כעס שיש לו מילים מחליף כעס שמתפרץ.", "freq": "באופן קבוע, בזמן רגוע", "approach": "TF-CBT", "targets": ["t5"], "sentences": ["מה הכי מכעיס אותך בזה?", "מה יעזור כשזה מתחיל לעלות?", "איך אני אדע שקשה לך?"]}, {"id": "i7", "name": "המבוגר מתקן", "what": "כשהמבוגר טעה, הוא אומר זאת בפשטות ומתקן.", "why": "מבוגר שמודה בטעות מלמד שאמון יכול לחזור.", "freq": "כשהמבוגר טועה", "approach": "DDP/PACE", "targets": ["t2", "t3"], "sentences": ["טעיתי קודם, ואני מצטער/ת", "תודה שנתת לי לתקן", "גם לי קורה לטעות"]}, {"id": "i8", "name": "תפקיד של אחריות", "what": "נותנים תפקיד אמיתי: נציגות בקבוצה, הובלת פעילות, או עזרה לצעירים בנוכחות מבוגר.", "why": "תפקיד אמיתי אומר לו/ה: סומכים עליך.", "freq": "לאורך התקופה", "approach": "ARC", "targets": ["t4", "t1"], "sentences": ["אני סומך/ת עליך בזה", "מה הרעיון שלך?", "הקבוצה צריכה מישהו כמוך"]}]}}}'::jsonb, true) on conflict (scope, institution, kind, title) do update set description = excluded.description, themes = excluded.themes, category = excluded.category, methods = excluded.methods, content = excluded.content, active = true where mercury_library.draft;
insert into public.mercury_library (scope, kind, title, description, themes, category, methods, content, draft) values ('mercury', 'goal', 'ויסות משותף בהצפה', 'להירגע בעזרת מבוגר רגוע כשהגוף מוצף', array['ויסות רגשי']::text[], 'ויסות רגשי', array['NMT', 'ויסות חושי', 'ARC', 'TBRI', 'Theraplay']::text[], '{"v": 2, "bank": 3, "review": 3, "avoid": "לא לצעוק, לא לאיים, ולא לבודד כעונש", "strengths": ["שיתוף פעולה", "סקרנות", "אמון"], "skills": ["ויסות בעזרת מבוגר"], "main": "2-5", "also": ["6-9"], "evidence": {"level": "derived", "note": "ויסות משותף הוא עיקרון מרכזי ב-NMT, ב-ARC וב-TBRI, ונתמך במחקר התפתחותי על ויסות בגיל הרך. הכלים הגופניים כאן (נשימה, קצב, לחץ עמוק) הם התאמה יישומית שטרם נבדקה כשלעצמה."}, "ages": {"2-5": {"targets": [{"id": "t1", "text": "כשקשה מאוד, מקבל/ת קרבה של מבוגר רגוע ונרגע/ת תוך זמן קצר יותר", "staff": "נרגע/ת כשאנחנו לידו/ה", "scale": ["עדיין מתקשה להירגע גם עם מבוגר", "נרגע/ת אחרי זמן רב, עם מבוגר", "נרגע/ת עם מבוגר בזמן קצר יותר", "נרגע/ת מהר עם מבוגר מוכר", "נרגע/ת עם מבוגרים שונים, ומתחיל/ה לבקש"]}, {"id": "t2", "text": "כשיש הזדמנות, משתמש/ת עם מבוגר בכלי גוף פשוט: נשימה, לחיצה או נדנוד", "staff": "מסכים/ה לנשום או להתנדנד איתנו", "scale": ["עדיין לא מסכים/ה לכלי גוף", "מסכים/ה לרגע, כשהמבוגר מציע", "משתמש/ת בכלי אחד עם מבוגר", "בוחר/ת כלי מתוך שניים", "מבקש/ת כלי בעצמו/ה, גם ממבוגר חדש"]}, {"id": "t3", "text": "אחרי רגע קשה, חוזר/ת לפעילות", "staff": "חוזר/ת לשחק אחרי שנרגע/ה", "scale": ["עדיין לא חוזר/ת לפעילות", "חוזר/ת אחרי זמן רב", "חוזר/ת עם מבוגר לצידו/ה", "חוזר/ת אחרי הרגעה קצרה", "חוזר/ת בעצמו/ה וממשיך/ה"]}, {"id": "t4", "text": "בהתפרצות, פוגע/ת פחות בעצמו/ה, באחרים ובחפצים", "staff": "פוגע/ת פחות כשקשה", "scale": ["עדיין פוגע/ת ברוב ההתפרצויות", "פוגע/ת לפעמים", "בוכה או צועק/ת בלי לפגוע", "מראה בגוף שקשה, בלי לפגוע", "מראה או אומר/ת שקשה, לפני שמתפרץ/ת"]}, {"id": "t5", "text": "כשמתחיל להיות קשה, מראה סימן מוסכם: כרטיס, תנועה או מילה", "staff": "מראה לנו את הסימן כשקשה", "scale": ["עדיין לא משתמש/ת בסימן", "מגיב/ה כשמבוגר מראה את הסימן", "מראה את הסימן כשמזכירים", "מראה את הסימן בעצמו/ה לפעמים", "מראה את הסימן ברוב הפעמים, לכל מבוגר"]}], "interventions": [{"id": "i1", "name": "מתקרבים לאט ובשקט", "what": "מתקרבים לאט, יורדים לגובה הילד/ה, ומדברים בקול נמוך ובמשפטים קצרים.", "why": "גוף רגוע של מבוגר מרגיע את הגוף של הילד/ה.", "freq": "כשקשה מאוד", "approach": "NMT", "targets": ["t1", "t4"], "sentences": ["אני כאן. אני איתך", "קשה לך עכשיו", "נחכה יחד"], "avoid": "לא להגיד לו/ה להירגע"}, {"id": "i2", "name": "נשימה משותפת", "what": "נושמים יחד לאט, למשל מנפחים בלון דמיוני או מכבים נר דמיוני.", "why": "נשימה איטית מאטה את הלב.", "freq": "כשקשה מאוד, ובזמנים רגועים לתרגול", "approach": "ויסות חושי", "targets": ["t2", "t1"], "sentences": ["בוא/י ננפח בלון גדול", "עוד פעם, לאט לאט", "נכבה ביחד את הנר"]}, {"id": "i3", "name": "תנועה בקצב", "what": "נדנוד, הליכה איטית יחד, תיפוף בקצב או שיר מוכר.", "why": "קצב חוזר מרגיע את הגוף.", "freq": "כשקשה מאוד", "approach": "NMT", "targets": ["t1", "t2"], "sentences": ["בוא/י נלך ביחד לאט", "נתופף ביחד", "נשיר את השיר שלנו"]}, {"id": "i4", "name": "לחץ עמוק בהסכמה", "what": "כרית ללחוץ, שמיכה רכה, או חיבוק חזק רק אם הילד/ה רוצה. שמיכה משוקללת רק בהנחיית ריפוי בעיסוק.", "why": "לחץ עמוק מרגיע את הגוף.", "freq": "כשקשה מאוד, לפי הצורך", "approach": "ויסות חושי", "targets": ["t2"], "sentences": ["רוצה את השמיכה הרכה?", "אפשר ללחוץ חזק על הכרית", "תגיד/י לי אם זה נעים"], "avoid": "לא לגעת או לחבק בלי הסכמה"}, {"id": "i5", "name": "פינת ההרגעה עם מבוגר", "what": "יוצאים יחד לפינת ההרגעה, והמבוגר נשאר קרוב.", "why": "פחות רעש ואור עוזרים לגוף להירגע.", "freq": "כשקשה מאוד", "approach": "ARC", "targets": ["t1", "t3", "t4"], "sentences": ["בוא/י נלך לפינת ההרגעה", "אני נשאר/ת איתך", "כשתרגיש/י מוכן/ה, נחזור"], "avoid": "לא לשלוח לבד לפינה כעונש"}, {"id": "i6", "name": "סימן מוסכם", "what": "בוחרים יחד בזמן רגוע סימן לקושי: כרטיס, תנועה או מילה, ומתרגלים אותו.", "why": "סימן פשוט מאפשר לבקש עזרה לפני ההתפרצות.", "freq": "בזמנים רגועים, ובכל פעם שהסימן מופיע", "approach": "TBRI", "targets": ["t5"], "sentences": ["זה הסימן שלך כשקשה", "ראיתי את הסימן, אני מגיע/ה", "בוא/י נתרגל את הסימן"]}, {"id": "i7", "name": "חזרה רכה לפעילות", "what": "אחרי שנרגע/ה, מציעים צעד קטן חזרה, בלי שיחה ארוכה על מה שקרה.", "why": "חזרה מהירה לשגרה מראה שהקשר לא נפגע.", "freq": "אחרי כל רגע קשה", "approach": "ARC", "targets": ["t3"], "sentences": ["רוצה לחזור לשחק?", "אני שמח/ה שחזרת", "נמשיך מאיפה שעצרנו"], "avoid": "לא לנזוף או להטיף אחרי שנרגע/ה"}, {"id": "i8", "name": "משחקי קצב ותנועה (בהשראת Theraplay)", "what": "משחקי קצב קצרים בזמן רגוע: מחיאות כפיים, מהר ולאט, רץ ועוצר. המטפלת מדריכה.", "why": "תרגול במשחק מכין את הגוף לרגעים קשים.", "freq": "באופן קבוע, בזמנים רגועים", "approach": "Theraplay", "targets": ["t2", "t4"], "sentences": ["עכשיו מהר! ועכשיו לאט", "ירוק רצים, אדום עוצרים", "איזה כיף, עוד פעם?"]}]}}}'::jsonb, true) on conflict (scope, institution, kind, title) do update set description = excluded.description, themes = excluded.themes, category = excluded.category, methods = excluded.methods, content = excluded.content, active = true where mercury_library.draft;
insert into public.mercury_library (scope, kind, title, description, themes, category, methods, content, draft) values ('mercury', 'goal', 'פינת הרגעה דרך הגוף', 'להכיר מקום וכלים שעוזרים לגוף להירגע', array['ויסות רגשי']::text[], 'ויסות רגשי', array['ויסות חושי', 'ARC', 'TBRI', 'NMT']::text[], '{"v": 2, "bank": 3, "review": 3, "avoid": "לא להשתמש בפינה כעונש או כבידוד", "strengths": ["סקרנות", "עצמאות", "יצירתיות"], "skills": ["שימוש בפינת הרגעה"], "main": "2-5", "also": ["6-9"], "evidence": {"level": "derived", "note": "נשען על עקרונות הוויסות החושי ועל ARC. פינות הרגעה נפוצות בגיל הרך, אך המחקר עליהן מוגבל; ההבחנה בין פינה מזמינה לבין בידוד כעונש נשענת על עקרונות הטיפול מותאם הטראומה."}, "ages": {"2-5": {"targets": [{"id": "t1", "text": "בזמן רגוע, מכיר/ה את פינת ההרגעה ומה יש בה", "staff": "יודע/ת מה יש בפינת ההרגעה", "scale": ["עדיין לא מכיר/ה את הפינה", "נכנס/ת לפינה עם מבוגר", "מכיר/ה חפץ אחד בפינה", "בוחר/ת חפץ מהפינה", "מראה לילד אחר מה יש בפינה"]}, {"id": "t2", "text": "כשקשה, הולך/ת לפינה עם מבוגר", "staff": "הולך/ת איתנו לפינה כשקשה", "scale": ["עדיין מסרב/ת ללכת לפינה", "הולך/ת כשמבוגר מוביל", "הולך/ת כשמציעים", "הולך/ת בעצמו/ה, ומבוגר מצטרף", "הולך/ת בעצמו/ה, גם במקום אחר"]}, {"id": "t3", "text": "בפינה, בוחר/ת כלי שעוזר לגוף: כרית, שמיכה, מוזיקה או צעצוע לחיץ", "staff": "בוחר/ת בפינה משהו שעוזר לו/ה", "scale": ["עדיין לא נוגע/ת בכלים", "משתמש/ת כשמבוגר נותן", "בוחר/ת מתוך שניים", "בוחר/ת לבד את מה שעוזר", "יודע/ת מה עוזר לו/ה, גם מחוץ לפינה"]}, {"id": "t4", "text": "חוזר/ת מהפינה לפעילות תוך זמן קצר", "staff": "חוזר/ת מהפינה לפעילות", "scale": ["עדיין נשאר/ת בפינה זמן רב", "חוזר/ת אחרי זמן רב", "חוזר/ת עם מבוגר", "חוזר/ת אחרי זמן קצר", "חוזר/ת בעצמו/ה ומראה מה עזר"]}, {"id": "t5", "text": "כשיש הזדמנות, משתמש/ת בכלי גוף גם מחוץ לפינה: בגן, בארוחה או בטיול", "staff": "משתמש/ת בכלי שעוזר גם במקומות אחרים", "scale": ["עדיין רק בפינה, עם מבוגר", "משתמש/ת בחוץ כשמבוגר מציע", "משתמש/ת בכלי אחד במקום מוכר", "משתמש/ת בכמה מקומות", "משתמש/ת בעצמו/ה בכל מקום"]}], "interventions": [{"id": "i1", "name": "בונים את הפינה יחד", "what": "בונים עם הילד/ה פינה שקטה ורכה: כריות, שמיכה, אור עמום וכמה חפצים לגוף.", "why": "פינה שעזרו לבנות מרגישה שלי.", "freq": "פעם אחת, ועדכון מדי פעם", "approach": "ARC", "targets": ["t1", "t3"], "sentences": ["בוא/י נבנה פינה רגועה", "מה לשים פה?", "זו הפינה שלנו להירגע"]}, {"id": "i2", "name": "מכירים את הפינה ברוגע", "what": "מבקרים בפינה דווקא בזמן רגוע, משחקים בכלים ומספרים במה כל אחד עוזר.", "why": "מה שמכירים ברוגע קל להשתמש בו בסערה.", "freq": "באופן קבוע, בזמנים רגועים", "approach": "TBRI", "targets": ["t1"], "sentences": ["בוא/י נבדוק מה יש בפינה", "הכרית הזאת טובה ללחוץ", "איזה דבר הכי נעים לך?"]}, {"id": "i3", "name": "מזמינים, לא שולחים", "what": "כשקשה מציעים ללכת יחד לפינה, ומבוגר נשאר בקרבת מקום.", "why": "הזמנה מרגיעה, ושליחה מרגישה כמו עונש.", "freq": "כשמתחיל להיות קשה", "approach": "ARC", "targets": ["t2"], "sentences": ["רוצה שנלך יחד לפינה?", "אני בא/ה איתך", "אפשר לנוח פה קצת"], "avoid": "לא להשאיר לבד בפינה"}, {"id": "i4", "name": "כלים לחושים", "what": "בפינה כמה כלים מוכרים: שמיכה רכה, צעצוע לחיץ, אוזניות, ובקבוק נצנצים מפלסטיק סגור היטב.", "why": "כל ילד נרגע דרך חוש אחר.", "freq": "תמיד בפינה", "approach": "ויסות חושי", "targets": ["t3"], "sentences": ["מה עוזר לגוף שלך עכשיו?", "רוצה את השמיכה הרכה?", "בוא/י נסתכל על הנצנצים יורדים"]}, {"id": "i5", "name": "כרטיס בחירה בתמונות", "what": "כרטיס עם תמונות של כלי ההרגעה, כדי לבחור גם בלי מילים.", "why": "בחירה בלי מילים קלה יותר כשהגוף מוצף.", "freq": "בכל שימוש בפינה", "approach": "TBRI", "targets": ["t3", "t2"], "sentences": ["תצביע/י לי מה בא לך", "זה? או זה?", "בחרת יופי"]}, {"id": "i6", "name": "שעון חול או שיר", "what": "שעון חול, שיר קצר או ספירה מסמנים כמה זמן נחים בפינה.", "why": "זמן צפוי עוזר לחזור לפעילות.", "freq": "בכל שימוש בפינה", "approach": "NMT", "targets": ["t4"], "sentences": ["נחכה עד שהחול ייגמר", "עוד שיר אחד, ואז נבדוק איך הגוף", "הגוף כבר יותר רגוע?"]}, {"id": "i7", "name": "חזרה עם מילה טובה", "what": "כשמוכן/ה לחזור, מלווים בחזרה ואומרים מה עזר.", "why": "מילה על מה שעזר מלמדת את הילד/ה מה עובד בשבילו/ה.", "freq": "בכל חזרה מהפינה", "approach": "ARC", "targets": ["t4"], "sentences": ["ראיתי שהשמיכה עזרה לך", "נחזור לשחק?", "הגוף שלך יודע להירגע"]}, {"id": "i8", "name": "כלי הרגעה נייד", "what": "כלי אחד קטן מהפינה, כמו צעצוע לחיץ או בד רך, נלקח לטיול, לגן או לארוחה.", "why": "כלי מוכר עוזר גם במקום חדש.", "freq": "ביציאה ממקום מוכר", "approach": "ויסות חושי", "targets": ["t5"], "sentences": ["ניקח את הכדור הלחיץ לטיול", "אם יהיה קשה, יש לך את זה", "ראיתי שהשתמשת בזה בגינה"]}]}}}'::jsonb, true) on conflict (scope, institution, kind, title) do update set description = excluded.description, themes = excluded.themes, category = excluded.category, methods = excluded.methods, content = excluded.content, active = true where mercury_library.draft;
insert into public.mercury_library (scope, kind, title, description, themes, category, methods, content, draft) values ('mercury', 'goal', 'לפנות למבוגר בהצפה', 'לבוא למבוגר כשמתחיל להיות קשה, לפני שזה מתפוצץ', array['ויסות רגשי']::text[], 'ויסות רגשי', array['TBRI', 'ARC', 'CPS', 'ויסות חושי', 'DDP/PACE']::text[], '{"v": 2, "bank": 3, "review": 3, "avoid": "לא להגיב בכעס כשהפנייה מגיעה בצעקה", "strengths": ["אומץ", "בקשת עזרה", "כנות"], "skills": ["פנייה למבוגר"], "main": "6-9", "also": ["10-12"], "evidence": {"level": "derived", "note": "נשען על ARC (ויסות ומסוגלות), TBRI ו-CPS, שנבדקו במסגרות לילדים. משפט או סימן אישי ותגובה אחידה של כל הצוות הם התאמה יישומית שטרם נבדקה כשלעצמה."}, "ages": {"6-9": {"targets": [{"id": "t1", "text": "כשמתחיל להיות קשה, פונה למבוגר לפני שהתחושה מציפה לגמרי", "staff": "בא/ה אלינו לפני שמתפוצץ/ת", "scale": ["עדיין מתפרץ/ת בלי לפנות", "פונה רק אחרי התפרצות", "פונה כשמבוגר מזהה ושואל", "פונה בעצמו/ה לפעמים", "פונה בזמן ברוב הפעמים"]}, {"id": "t2", "text": "משתמש/ת בסימן או במשפט קבוע כדי לבקש הפסקה או עזרה", "staff": "אומר/ת את המשפט שלו/ה כשצריך הפסקה", "scale": ["עדיין לא משתמש/ת בסימן", "משתמש/ת כשמבוגר מזכיר", "משתמש/ת בסימן בתנועה", "אומר/ת את המשפט במילים", "בוחר/ת למי ואיך לפנות"]}, {"id": "t3", "text": "מקבל/ת את ההצעה של המבוגר: הפסקה, נשימה או יציאה", "staff": "מסכים/ה להצעה שלנו להירגע", "scale": ["עדיין דוחה כל הצעה", "מקבל/ת אחרי ויכוח", "מקבל/ת הצעה אחת קבועה", "מקבל/ת ובוחר/ת מתוך שתיים", "מציע/ה בעצמו/ה מה יעזור"]}, {"id": "t4", "text": "אחרי שנרגע/ה, מדבר/ת בקצרה עם המבוגר על מה שהיה", "staff": "מדבר/ת איתנו אחרי שנרגע/ה", "scale": ["עדיין נמנע/ת מלדבר על זה", "עונה במילה אחת", "מספר/ת מה קרה כששואלים", "מספר/ת גם מה הרגיש/ה", "מציע/ה מה לעשות בפעם הבאה"]}, {"id": "t5", "text": "פונה גם למבוגרים שונים ובמקומות שונים: במרכז, בחצר ובבית הספר", "staff": "פונה לכל מבוגר, בכל מקום", "scale": ["עדיין פונה למבוגר אחד או לאף אחד", "פונה לשני מבוגרים מוכרים", "פונה לרוב הצוות במרכז", "פונה גם בבית הספר", "פונה למבוגר מתאים בכל מקום"]}], "interventions": [{"id": "i1", "name": "משפט או סימן אישי", "what": "בוחרים יחד בזמן רגוע משפט או סימן שאומר: קשה לי, צריך הפסקה. כותבים אותו על כרטיס.", "why": "משפט מוכן זמין גם כשהראש מוצף.", "freq": "בזמן רגוע, ותרגול מדי פעם", "approach": "CPS", "targets": ["t2"], "sentences": ["איזה משפט נוח לך להגיד?", "אפשר להגיד: קשה לי, צריך הפסקה", "בוא/י נתרגל אותו עכשיו"]}, {"id": "i2", "name": "הפסקה מאושרת מיד", "what": "כשמראה את הסימן או אומר/ת את המשפט, מאשרים הפסקה מיד, בלי שאלות ובלי ויכוח.", "why": "כשהסימן עובד מיד, כדאי להשתמש בו שוב.", "freq": "בכל פנייה", "approach": "TBRI", "targets": ["t1", "t2"], "sentences": ["ראיתי את הסימן, בוא/י נצא", "הפסקה אושרה, אני איתך", "נדבר אחר כך, עכשיו נרגעים"]}, {"id": "i3", "name": "מקבלים גם פנייה לא מושלמת", "what": "גם כשהפנייה בצעקה או בבכי, קודם עוזרים, ורק אחר כך עובדים על הדרך.", "why": "קבלה קודם בונה רצון לפנות שוב.", "freq": "בכל פנייה", "approach": "DDP/PACE", "targets": ["t1"], "sentences": ["אני רואה שקשה לך מאוד", "באת אליי, וזה חשוב", "על המילים נדבר אחר כך"], "avoid": "לא לדרוש לדבר יפה לפני שעוזרים"}, {"id": "i4", "name": "שתי דרכים להירגע", "what": "מציעים שתי דרכים ברורות להירגע, והילד/ה בוחר/ת.", "why": "בחירה מחזירה תחושת שליטה.", "freq": "בכל פנייה", "approach": "TBRI", "targets": ["t3"], "sentences": ["רוצה לצאת לחצר או לשבת בפינה?", "מים או נשימה?", "בחרת, בוא/י נלך"]}, {"id": "i5", "name": "כלי גוף מהירים", "what": "כלים קצרים: לשתות מים קרים, לדחוף קיר, לקפוץ, לנשום עם ספירה.", "why": "הגוף נרגע לפני שהראש יכול לחשוב.", "freq": "בזמן קושי", "approach": "ויסות חושי", "targets": ["t3"], "sentences": ["בוא/י נדחוף את הקיר חזק", "ננשום ביחד: ארבע פנימה, ארבע החוצה", "נשתה מים קרים"]}, {"id": "i6", "name": "שיחה קצרה אחרי אירוע", "what": "אחרי שנרגע/ה, כמה דקות: מה קרה, מה עזר, מה ננסה בפעם הבאה. בלי עונש בשיחה.", "why": "שיחה רגועה הופכת אירוע ללמידה.", "freq": "אחרי אירוע, כשרגוע", "approach": "CPS", "targets": ["t4"], "sentences": ["מה עזר לך היום?", "מה ננסה בפעם הבאה?", "התמודדת, גם כשהיה קשה"], "avoid": "לא לנהל את השיחה כשעדיין קשה לו/ה"}, {"id": "i7", "name": "כל הצוות מכיר את הסימן", "what": "הסימן והמשפט כתובים בתוכנית, וכל המדריכים מגיבים אליו באותה דרך. בתיאום עם המטפלת ובהסכמת הילד/ה, מעדכנים גם את בית הספר.", "why": "כשכולם מגיבים אותו דבר, הסימן עובד בכל מקום.", "freq": "באופן קבוע", "approach": "ARC", "targets": ["t5"], "sentences": ["גם המדריך של הלילה מכיר את הסימן שלך", "נבדוק יחד אם לספר גם בבית הספר", "אפשר להשתמש בו עם כולם"]}, {"id": "i8", "name": "תזכורת שקטה לסימן", "what": "כשרואים שמתחיל להיות קשה, ניגשים בשקט ומזכירים את הסימן, לא מול הקבוצה.", "why": "תזכורת שקטה עוזרת לפנות לפני שזה מתפוצץ.", "freq": "כשמתחיל להיות קשה", "approach": "ARC", "targets": ["t1", "t2"], "sentences": ["נראה לי שמתחיל להיות קשה", "רוצה להשתמש בסימן שלך?", "אני כאן, בשקט"]}]}}}'::jsonb, true) on conflict (scope, institution, kind, title) do update set description = excluded.description, themes = excluded.themes, category = excluded.category, methods = excluded.methods, content = excluded.content, active = true where mercury_library.draft;
insert into public.mercury_library (scope, kind, title, description, themes, category, methods, content, draft) values ('mercury', 'goal', 'לזהות מוקדם שמתחמם לי', 'לשים לב לסימנים בגוף ולעצור לפני שהכעס או הפחד מתפרצים', array['ויסות רגשי']::text[], 'ויסות רגשי', array['TF-CBT', 'ARC', 'ויסות חושי', 'CPS', 'TBRI']::text[], '{"v": 2, "bank": 3, "review": 3, "avoid": "לא לתייג את הילד/ה כעצבני/ת מול אחרים", "strengths": ["סקרנות", "כנות", "התמדה"], "skills": ["זיהוי סימנים בגוף"], "main": "6-9", "also": ["10-12"], "evidence": {"level": "derived", "note": "זיהוי רגשות וסימנים גופניים הוא רכיב של TF-CBT, שנבדק מחקרית בילדים אחרי טראומה, ושל ARC. מד רגשי ומפת גוף כפעולות צוות הם התאמה יישומית; את מפת הגוף עושים בהנחיית המטפלת."}, "ages": {"6-9": {"targets": [{"id": "t1", "text": "בזמן רגוע, מראה על מפת הגוף איפה מרגיש/ה כעס או פחד", "staff": "מראה איפה בגוף מרגיש/ה כעס", "scale": ["עדיין לא מזהה תחושה בגוף", "מראה כשמבוגר מציע אפשרויות", "מראה מקום אחד בגוף", "מראה כמה מקומות ומה מרגיש/ה", "מתאר/ת את הסימנים במילים שלו/ה"]}, {"id": "t2", "text": "משתמש/ת במד רגשי (1 עד 5, או צבעים) כדי לומר כמה חזק", "staff": "אומר/ת לנו כמה חם לו/ה, לפי המד", "scale": ["עדיין לא משתמש/ת במד", "מצביע/ה על המד כשמבוגר שואל", "מצביע/ה גם בזמן קושי", "אומר/ת את המספר בעצמו/ה", "משתמש/ת במד בלי כרטיס, במילים"]}, {"id": "t3", "text": "כשהמד עולה, בוחר/ת כלי מוכר לפני ההתפרצות", "staff": "עושה משהו שמרגיע כשמתחיל לעלות", "scale": ["עדיין מתפרץ/ת כשהמד עולה", "משתמש/ת בכלי כשמבוגר מציע", "משתמש/ת בכלי אחד קבוע", "בוחר/ת כלי מתוך כמה", "בוחר/ת כלי בעצמו/ה, בזמן"]}, {"id": "t4", "text": "מזהה מה בדרך כלל מעלה לו/ה את המד: רעש, הפסד, שינוי או פרידה", "staff": "יודע/ת מה מעצבן או מלחיץ אותו/ה", "scale": ["עדיין לא מזהה מה מעלה", "מזהה כשמבוגר מציע", "מזהה דבר אחד", "מזהה כמה דברים", "מתכנן/ת מראש איך להתכונן אליהם"]}, {"id": "t5", "text": "כשיש הזדמנות, משתמש/ת במד ובכלים גם בבית הספר או בביקור", "staff": "משתמש/ת במד גם מחוץ למרכז", "scale": ["עדיין רק במרכז ועם מבוגר", "במרכז, בעצמו/ה", "בבית הספר כשמזכירים", "בבית הספר בעצמו/ה", "בכל מקום, גם בלי כרטיס"]}], "interventions": [{"id": "i1", "name": "מפת הגוף (בהשראת TF-CBT)", "what": "מציירים יחד צללית של גוף, וצובעים איפה מרגישים כעס, פחד או שמחה. המטפלת מדריכה.", "why": "כשמזהים בגוף, אפשר לעצור מוקדם.", "freq": "כמה פעמים, בזמן רגוע", "approach": "TF-CBT", "targets": ["t1"], "sentences": ["איפה בגוף מרגישים כעס?", "הידיים נהיות חמות? הבטן מתכווצת?", "מעניין, אצלך זה בכתפיים"]}, {"id": "i2", "name": "מד רגשי", "what": "כרטיס עם מד מ-1 (רגוע) עד 5 (מתפוצץ), בצבעים. בודקים איתו כמה פעמים ביום.", "why": "מספר פשוט עוזר לשים לב לפני שמאוחר.", "freq": "כמה פעמים ביום", "approach": "ARC", "targets": ["t2"], "sentences": ["כמה חם לך עכשיו, מ-1 עד 5?", "אתמול היית בשלוש, וזה עבר", "שתיים. תודה שבדקת איתי"]}, {"id": "i3", "name": "כלי לכל מספר", "what": "מסכמים יחד מה עושים בכל מספר: בשלוש שותים מים, בארבע יוצאים עם מבוגר.", "why": "תוכנית מוכנה חוסכת חשיבה ברגע קשה.", "freq": "פעם אחת, ובדיקה מדי פעם", "approach": "CPS", "targets": ["t3"], "sentences": ["מה עוזר לך בשלוש?", "בוא/י נכתוב את זה על הכרטיס", "בארבע, למי פונים?"]}, {"id": "i4", "name": "בלשים של המד", "what": "בזמן רגוע מחפשים יחד, כמו בלשים, מה מעלה את המד: רעש, הפסד או שינוי.", "why": "מה שמזהים מראש מפתיע פחות.", "freq": "אחרי אירועים, כשרגוע", "approach": "CPS", "targets": ["t4"], "sentences": ["בוא/י נהיה בלשים: מה העלה את המד?", "שמתי לב שרעש חזק מעלה לך", "מה אפשר לעשות לפני שזה קורה?"]}, {"id": "i5", "name": "המבוגר אומר מה רואה", "what": "כשרואים סימן מוקדם, אומרים בעדינות מה רואים, בלי ביקורת.", "why": "כשאומרים בקול, הילד/ה לומד/ת לשים לב בעצמו/ה.", "freq": "כשמופיע סימן", "approach": "ARC", "targets": ["t1", "t3"], "sentences": ["אני רואה שהידיים שלך קפוצות", "נראה לי שהמד מתחיל לעלות", "מה יעזור עכשיו?"], "avoid": "לא להגיד ''שוב מתחילים'' בטון מאשים"}, {"id": "i6", "name": "כלי גוף לפי המד", "what": "כשהמד עולה, בוחרים כלי גוף מהרשימה: לשתות מים, ללחוץ כדור, ללכת מהר.", "why": "כלי גוף מוריד את המד מהר.", "freq": "כשהמד עולה", "approach": "ויסות חושי", "targets": ["t3"], "sentences": ["המד עולה? בוא/י נבחר כלי", "קח/י את הכדור הלחיץ", "בוא/י נלך הליכה מהירה"]}, {"id": "i7", "name": "כרטיס בכיס", "what": "כרטיס קטן עם המד והכלים, שהילד/ה לוקח/ת לבית הספר ולביקורים. בתיאום עם המטפלת ובהסכמת הילד/ה, מעבירים עותק לבית הספר.", "why": "כך משתמשים בכלים גם במקום אחר.", "freq": "ביציאה מהמרכז", "approach": "ARC", "targets": ["t5"], "sentences": ["הכרטיס שלך בא איתך", "גם בבית הספר יודעים על הכרטיס", "איך הלך עם הכרטיס היום?"]}, {"id": "i8", "name": "שבח על עצירה", "what": "משבחים בדיוק כשעצר/ה בזמן או השתמש/ה בכלי.", "why": "שבח מדויק מחזק את מה שרוצים שיחזור.", "freq": "בכל הצלחה", "approach": "TBRI", "targets": ["t3", "t5"], "sentences": ["עצרת בזמן, וזה ממש קשה", "ראיתי שלקחת נשימה", "המד ירד בזכות מה שעשית"]}]}}}'::jsonb, true) on conflict (scope, institution, kind, title) do update set description = excluded.description, themes = excluded.themes, category = excluded.category, methods = excluded.methods, content = excluded.content, active = true where mercury_library.draft;
insert into public.mercury_library (scope, kind, title, description, themes, category, methods, content, draft) values ('mercury', 'goal', 'תוכנית ויסות אישית', 'לכתוב יחד תוכנית: מה מלחיץ, איך מזהים, ומה עוזר', array['ויסות רגשי']::text[], 'ויסות רגשי', array['ARC', 'CPS', 'TBRI', 'ויסות חושי', 'DDP/PACE']::text[], '{"v": 2, "bank": 3, "review": 3, "avoid": "לא לכתוב את התוכנית בלי הילד/ה, ולא להפוך אותה לרשימת עונשים", "strengths": ["אחריות", "כנות", "יצירתיות", "התמדה"], "skills": ["תכנון מראש"], "main": "10-12", "also": ["13-15"], "evidence": {"level": "derived", "note": "נשען על ARC, CPS ורכיבי ההתמודדות של TF-CBT. תוכנית ויסות כתובה בשותפות הילד/ה ושיחת בדיקה אחרי אירוע הן פרקטיקה מקובלת במסגרות מגורים, וטרם נבדקו כשלעצמן."}, "ages": {"10-12": {"targets": [{"id": "t1", "text": "משתתף/ת בכתיבת תוכנית ויסות אישית: סימנים, מצבים קשים וכלים", "staff": "כותב/ת איתנו תוכנית הרגעה", "scale": ["עדיין לא מוכן/ה לדבר על זה", "עונה על כמה שאלות", "מציע/ה רעיון אחד לתוכנית", "כותב/ת חלק גדול מהתוכנית", "מעדכן/ת את התוכנית בעצמו/ה"]}, {"id": "t2", "text": "בזמן קושי, משתמש/ת בכלי מהתוכנית", "staff": "משתמש/ת בכלי מהתוכנית כשקשה", "scale": ["עדיין לא משתמש/ת בכלים", "משתמש/ת כשמבוגר מזכיר", "משתמש/ת בכלי אחד קבוע", "בוחר/ת כלי מתאים בעצמו/ה", "משתמש/ת בכלים לפני שקשה מדי"]}, {"id": "t3", "text": "כשיש הזדמנות, משתמש/ת בתוכנית גם בבית הספר ובחוגים", "staff": "משתמש/ת בתוכנית גם בבית הספר", "scale": ["עדיין רק במרכז", "בבית הספר, עם תזכורת", "בבית הספר לפעמים, בעצמו/ה", "ברוב המקומות", "בכל מקום, ומספר/ת למבוגר חדש מה עוזר"]}, {"id": "t4", "text": "אחרי אירוע, בודק/ת עם מבוגר מה עבד ומה לא", "staff": "בודק/ת איתנו אחרי אירוע מה עבד", "scale": ["עדיין נמנע/ת משיחה אחרי אירוע", "מסכים/ה לשיחה קצרה", "אומר/ת מה עבד", "אומר/ת מה עבד ומה לא", "מציע/ה שינוי בתוכנית"]}, {"id": "t5", "text": "מספר/ת למבוגר כשמתחיל להיות קשה, לפני שמגיע/ה לשיא", "staff": "מספר/ת לנו כשמתחיל להיות קשה", "scale": ["עדיין מגיע/ה לשיא בלי לספר", "מספר/ת אחרי השיא", "מספר/ת כששואלים", "מספר/ת בעצמו/ה לפעמים", "מספר/ת בזמן ברוב הפעמים"]}], "interventions": [{"id": "i1", "name": "כותבים תוכנית יחד", "what": "דף קצר בשפה של הילד/ה: הסימנים שלי, מה מלחיץ אותי, מה עוזר, למי פונים.", "why": "תוכנית שכתבו יחד מרגישה שלי, ולכן משתמשים בה.", "freq": "פעם אחת, ועדכון מדי פעם", "approach": "CPS", "targets": ["t1"], "sentences": ["זו התוכנית שלך, במילים שלך", "מה הכי עוזר לך כשקשה?", "למי נוח לך לפנות?"]}, {"id": "i2", "name": "כל הצוות מכיר את התוכנית", "what": "התוכנית שמורה בתיק הטיפולי, וכל משמרת יודעת מה עוזר ומה לא.", "why": "תגובה אחידה מכל מבוגר מחזקת את התוכנית.", "freq": "באופן קבוע", "approach": "ARC", "targets": ["t2", "t3"], "sentences": ["סיפרתי למשמרת של הערב מה עוזר לך", "גם המדריך של הלילה מכיר את התוכנית", "אם משהו לא עובד, נעדכן את כולם"]}, {"id": "i3", "name": "תזכורת שקטה", "what": "כשרואים סימן מהתוכנית, מזכירים בעדינות ובשקט, לא מול הקבוצה.", "why": "תזכורת שקטה שומרת על כבוד ועוזרת לעצור.", "freq": "כשמופיע סימן", "approach": "TBRI", "targets": ["t2", "t5"], "sentences": ["נראה לי שזה הרגע לתוכנית", "מה מהרשימה שלך יעזור עכשיו?", "אני כאן אם צריך"]}, {"id": "i4", "name": "כלים לגוף ולראש", "what": "בתוכנית יש כלים לגוף (ספורט, מים, מוזיקה) וכלים לראש (לספור, לכתוב, לצייר).", "why": "יש רגעים שהגוף צריך להירגע לפני שאפשר לחשוב.", "freq": "בזמן קושי", "approach": "ויסות חושי", "targets": ["t2"], "sentences": ["גוף או ראש? מה צריך עכשיו?", "בוא/י נצא לסיבוב הליכה", "רוצה אוזניות ומוזיקה?"]}, {"id": "i5", "name": "שיחה קצרה אחרי אירוע", "what": "כשרגוע, שיחה קצרה: מה קרה, מה עזר, מה לשנות בתוכנית. בלי עונש בשיחה.", "why": "כל אירוע הוא הזדמנות לשפר את התוכנית.", "freq": "אחרי אירועים", "approach": "CPS", "targets": ["t4"], "sentences": ["מה עבד היום?", "מה היית משנה בתוכנית?", "היה קשה, והתמודדת"], "avoid": "לא לקיים את השיחה כשעדיין קשה לו/ה"}, {"id": "i6", "name": "גשר לבית הספר", "what": "בתיאום עם המטפלת ובהסכמת הילד/ה, מעבירים לבית הספר גרסה קצרה של התוכנית.", "why": "תוכנית שעובדת בכל מקום מחזקת עצמאות.", "freq": "בתחילת התקופה, ועדכון לפי הצורך", "approach": "ARC", "targets": ["t3"], "sentences": ["מה חשוב שידעו בבית הספר?", "נבחר יחד מה לשתף", "איך היה בבית הספר עם התוכנית?"], "avoid": "לא לשתף פרטים אישיים בלי הסכמה"}, {"id": "i7", "name": "סקרנות בלי שיפוט", "what": "מתארים מה רואים בסקרנות, ומקבלים את הרגש גם כשההתנהגות לא מקובלת.", "why": "כשמקבלים את הרגש, קל יותר להירגע.", "freq": "בזמני קושי", "approach": "DDP/PACE", "targets": ["t5", "t2"], "sentences": ["אני רואה שמשהו מציק לך", "הגיוני שזה מעצבן", "בוא/י נחשוב יחד מה עכשיו"]}, {"id": "i8", "name": "שבח על שימוש בתוכנית", "what": "משבחים בדיוק כשהשתמש/ה בתוכנית, גם אם רק בחלק ממנה.", "why": "הכרה בהצלחות קטנות שומרת על המוטיבציה.", "freq": "בכל שימוש", "approach": "TBRI", "targets": ["t2", "t3"], "sentences": ["השתמשת בתוכנית שלך, ראיתי", "גם חצי הצלחה היא הצלחה", "מה עזר לך הכי הרבה?"]}]}}}'::jsonb, true) on conflict (scope, institution, kind, title) do update set description = excluded.description, themes = excluded.themes, category = excluded.category, methods = excluded.methods, content = excluded.content, active = true where mercury_library.draft;
insert into public.mercury_library (scope, kind, title, description, themes, category, methods, content, draft) values ('mercury', 'goal', 'ארגז כלים לוויסות עצמאי', 'להכיר את הכלים שעובדים לי ולהשתמש בהם בעצמי', array['ויסות רגשי']::text[], 'ויסות רגשי', array['TF-CBT', 'ARC', 'CPS', 'ויסות חושי', 'סמכות חדשה']::text[], '{"v": 2, "bank": 3, "review": 3, "avoid": "לא להתווכח בשיא הסערה, ולא לקחת כלים כעונש", "strengths": ["אחריות", "עצמאות", "מודעות עצמית", "עמידות"], "skills": ["ויסות עצמאי"], "main": "13-15", "also": [], "evidence": {"level": "derived", "note": "כלי ההתמודדות נשענים על TF-CBT, שנבדק מחקרית במתבגרים אחרי טראומה, ועל ARC. תוכנית הביטחון בנויה לפי מודל Stanley-Brown ונכתבת בהנחיית המטפלת. ההתאמה לשגרת הצוות במסגרת חירום טרם נבדקה."}, "ages": {"13-15": {"targets": [{"id": "t1", "text": "מכיר/ה לפחות שלושה כלים שעובדים לו/ה, ומשתמש/ת בהם", "staff": "יודע/ת מה עוזר לו/ה ומשתמש/ת בזה", "scale": ["עדיין לא מזהה מה עוזר", "מזהה כלי אחד כששואלים", "משתמש/ת בכלי אחד בעצמו/ה", "משתמש/ת בכמה כלים לפי המצב", "בוחר/ת כלי מתאים בכל מצב"]}, {"id": "t2", "text": "כשקשה, מבקש/ת הפסקה או מרחב במקום להתפרץ", "staff": "מבקש/ת הפסקה כשקשה", "scale": ["עדיין מתפרץ/ת בלי לבקש", "יוצא/ת בכעס בלי לומר", "מבקש/ת הפסקה כשמזכירים", "מבקש/ת הפסקה בעצמו/ה", "מבקש/ת הפסקה וחוזר/ת לבד"]}, {"id": "t3", "text": "חוזר/ת לפעילות או לשיחה אחרי הפסקה", "staff": "חוזר/ת אחרי שנרגע/ה", "scale": ["עדיין לא חוזר/ת באותו יום", "חוזר/ת אחרי זמן רב", "חוזר/ת כשמבוגר מזמין", "חוזר/ת בעצמו/ה", "חוזר/ת ומדבר/ת על מה שהיה"]}, {"id": "t4", "text": "כשיש הזדמנות, משתמש/ת בכלים גם מחוץ למרכז: בבית הספר, בביקור או מול חברים", "staff": "משתמש/ת בכלים גם מחוץ למרכז", "scale": ["עדיין רק במרכז, עם מבוגר", "במרכז, בעצמו/ה", "מחוץ למרכז לפעמים", "ברוב המקומות", "בכל מקום, ומספר/ת מה עבד"]}, {"id": "t5", "text": "במצוקה חזקה, פונה למבוגר לפי תוכנית הביטחון", "staff": "פונה אלינו כשממש קשה", "scale": ["עדיין לא פונה במצוקה חזקה", "פונה אחרי שמבוגר מזהה", "פונה למבוגר אחד מוכר", "פונה בעצמו/ה, בזמן", "פונה בזמן ויודע/ת מה כתוב בתוכנית"]}], "interventions": [{"id": "i1", "name": "ארגז כלים אישי (בהשראת TF-CBT)", "what": "בונים יחד רשימה של כלים: מוזיקה, ספורט, כתיבה, מקלחת, שיחה עם מישהו. המטפלת מדריכה.", "why": "כשיש רשימה מוכנה, לא צריך להמציא ברגע קשה.", "freq": "פעם אחת, ועדכון מדי פעם", "approach": "TF-CBT", "targets": ["t1"], "sentences": ["מה עוזר לך בדרך כלל?", "בוא/י נכתוב את זה", "מה עוד שווה לנסות?"]}, {"id": "i2", "name": "הפסקה מכובדת", "what": "מסכמים מראש איך מבקשים הפסקה ולאן יוצאים, והמבוגר מאשר בלי ויכוח.", "why": "הפסקה מוסכמת מונעת פיצוץ ושומרת על כבוד.", "freq": "בכל בקשה", "approach": "ARC", "targets": ["t2", "t3"], "sentences": ["צריך הפסקה? סגור, אני בודק/ת איתך עוד מעט", "קח/י את הזמן שלך", "כשתרגיש/י מוכן/ה, נמשיך"]}, {"id": "i3", "name": "דחיית תגובה", "what": "בשיא הסערה לא מתווכחים ולא מענישים. אומרים שנדבר כשיהיה רגוע, וחוזרים לזה.", "why": "שיחה ברוגע משפיעה יותר מתגובה בסערה.", "freq": "בזמן סערה", "approach": "סמכות חדשה", "targets": ["t2", "t3"], "sentences": ["עכשיו לא נדבר, נחזור לזה כשיהיה רגוע", "אני כאן בשבילך", "זה חשוב לי, אז נדבר אחר כך"], "avoid": "לא להיכנס לוויכוח מול הקבוצה"}, {"id": "i4", "name": "כלים לגוף", "what": "כלים שמרגיעים את הגוף מהר: ספורט, מים קרים על הפנים, מוזיקה באוזניות, הליכה.", "why": "כשהגוף רגוע, הראש חוזר לעבוד.", "freq": "בזמן קושי", "approach": "ויסות חושי", "targets": ["t1"], "sentences": ["רוצה לצאת לסיבוב?", "אוזניות ומוזיקה?", "מים קרים על הפנים עוזרים להרבה אנשים"]}, {"id": "i5", "name": "שיחה קצרה אחרי אירוע", "what": "אחרי אירוע, שיחה בהליכה או ליד שולחן, בסקרנות ולא בחקירה: מה עזר ומה לא.", "why": "כבוד ושותפות מעודדים לקחת אחריות.", "freq": "אחרי אירועים, כשרגוע", "approach": "CPS", "targets": ["t3", "t1"], "sentences": ["מה עזר לך היום?", "מה היית עושה אחרת?", "אני סקרן/ית מה עבר עליך"]}, {"id": "i6", "name": "תוכנית ביטחון (בהנחיית המטפלת)", "what": "את תוכנית הביטחון כותבת המטפלת עם הנער/ה: סימני אזהרה, כלים, ולמי פונים. הצוות מכיר אותה ופועל לפיה.", "why": "במצוקה חזקה צריך דרך ברורה לקבל עזרה.", "freq": "לפי הנחיית המטפלת", "approach": "ARC", "targets": ["t5"], "sentences": ["אם ממש קשה, אני כאן, ותמיד אפשר לפנות", "מה כתוב בתוכנית שלך?", "תודה שסיפרת לי, נטפל בזה יחד"], "avoid": "לא להבטיח סודיות כשיש סכנה"}, {"id": "i7", "name": "מתכוננים ליציאה", "what": "לפני יציאה לבית הספר או לביקור מתכננים יחד: מה עלול להיות קשה, ואיזה כלי לוקחים.", "why": "תכנון מראש מעביר את הכלים לחיים בחוץ.", "freq": "לפני יציאות", "approach": "CPS", "targets": ["t4"], "sentences": ["מה עלול להיות קשה היום?", "איזה כלי לוקחים איתך?", "איך הלך? מה עבד?"]}, {"id": "i8", "name": "אחריות על הכלים", "what": "נותנים לנער/ה לנהל בעצמו/ה חלק מהכלים: לבחור מוזיקה, לקבוע הפסקה, לעדכן את הרשימה.", "why": "כשהכלים בידיים שלו/ה, הוא/היא סומך/ת על עצמו/ה.", "freq": "לאורך התקופה", "approach": "ARC", "targets": ["t4", "t1"], "sentences": ["את הרשימה מעדכנים לפי מה שמתאים לך", "אני סומך/ת עליך שתדע/י מה עוזר", "ספר/י לי מה עבד השבוע"]}]}}}'::jsonb, true) on conflict (scope, institution, kind, title) do update set description = excluded.description, themes = excluded.themes, category = excluded.category, methods = excluded.methods, content = excluded.content, active = true where mercury_library.draft;
insert into public.mercury_library (scope, kind, title, description, themes, category, methods, content, draft) values ('mercury', 'goal', 'פרידות קטנות ביום', 'ללמוד שפרידות ביום צפויות, ושאפשר להיפרד ולהמשיך', array['אובדן ופרידה']::text[], 'אובדן ופרידה', array['מעגל הביטחון', 'ARC', 'DDP/PACE', 'Theraplay', 'NMT']::text[], '{"v": 2, "bank": 3, "review": 3, "avoid": "לא להתגנב ולהיעלם בלי פרידה", "strengths": ["אמון", "סקרנות", "אומץ"], "skills": ["התמודדות עם פרידה"], "main": "2-5", "also": ["6-9"], "evidence": {"level": "derived", "note": "נגזר מתיאוריית ההתקשרות ומגישת מעגל הביטחון, ומ-ARC. טקסי פרידה ומשחקי היעלמות וחזרה הם פרקטיקה מקובלת בגיל הרך; השימוש בהם כשגרת צוות במרכז חירום טרם נבדק."}, "ages": {"2-5": {"targets": [{"id": "t1", "text": "בפרידה בבוקר, לגן או לבית הספר, נפרד/ת וממשיך/ה ליום תוך זמן קצר", "staff": "נפרד/ת וממשיך/ה ליום", "scale": ["עדיין מתקשה מאוד בכל פרידה", "נפרד/ת בעזרה רבה, ובוכה זמן רב", "נפרד/ת בעזרה ונרגע/ת", "נפרד/ת ונרגע/ת מהר", "נפרד/ת בקלות ממבוגרים שונים"]}, {"id": "t2", "text": "כשמבוגר חוזר, מקבל/ת אותו במבט, בחיוך, בריצה או במילה", "staff": "שמח/ה לקראתנו כשאנחנו חוזרים", "scale": ["עדיין מתעלם/ת או כועס/ת בחזרה", "מסתכל/ת מרחוק", "ניגש/ת אחרי זמן", "ניגש/ת מהר ושמח/ה", "מספר/ת מה עשה/תה בזמן שהמבוגר לא היה"]}, {"id": "t3", "text": "כשחבר מהקבוצה עוזב את המרכז, משתתף/ת בפרידה", "staff": "נפרד/ת מילדים שעוזבים", "scale": ["עדיין מתנתק/ת או מתפרץ/ת", "מסתכל/ת על הפרידה מהצד", "משתתף/ת בפרידה עם מבוגר", "מכין/ה משהו קטן לפרידה", "מדבר/ת על מי שעזב ונזכר/ת בו"]}, {"id": "t4", "text": "כשיש הזדמנות, משחק/ת במשחקי היעלמות וחזרה, כמו מחבואים", "staff": "משחק/ת במחבואים בהנאה", "scale": ["עדיין נבהל/ת כשמשהו נעלם", "משחק/ת קצר עם מבוגר צמוד", "משחק/ת ומחכה לחזרה", "משחק/ת ויוזם/ת את המשחק", "יוזם/ת משחקי היעלמות גם עם מבוגרים שונים"]}, {"id": "t5", "text": "אחרי פרידה, אומר/ת או מראה מתי המבוגר יחזור", "staff": "יודע/ת מתי נחזור", "scale": ["עדיין לא יודע/ת מה קורה", "מסתכל/ת על הלוח כשמראים", "מראה בלוח כששואלים", "אומר/ת מתי המבוגר חוזר", "אומר/ת בעצמו/ה מתי המבוגר חוזר, ונרגע/ת"]}], "interventions": [{"id": "i1", "name": "טקס פרידה קצר", "what": "אותו טקס בכל פרידה: חיבוק (אם הילד/ה רוצה) או כיף, משפט קבוע, ומי נשאר. קצר, בלי להאריך.", "why": "פרידה צפויה וקצרה מפחידה פחות.", "freq": "בכל פרידה", "approach": "ARC", "targets": ["t1"], "sentences": ["ביי, אחרי הצהריים אוספים אותך", "עכשיו ממשיכים לשחק, ואחר כך נתראה", "כיף של פרידה, ויוצאים לדרך"], "avoid": "לא להאריך את הפרידה, ולא להתגנב"}, {"id": "i2", "name": "חזרה חמה", "what": "כשחוזרים, מחפשים את הילד/ה, מברכים בחום ומזכירים שאמרנו שנחזור.", "why": "חזרה שמקיימת את מה שנאמר בונה אמון.", "freq": "בכל חזרה", "approach": "מעגל הביטחון", "targets": ["t2", "t5"], "sentences": ["חזרתי, כמו שאמרתי", "התגעגעתי אליך", "ספר/י לי מה עשית"]}, {"id": "i3", "name": "משחקי היעלמות (בהשראת Theraplay)", "what": "מחבואים, \"איפה הבובה\", המבוגר מסתתר מאחורי בד או ידיים: משחקים קצרים של נעלם וחוזר. לא מכסים את הפנים של הילד/ה. המטפלת מדריכה.", "why": "במשחק מתרגלים היעלמות וחזרה בלי פחד.", "freq": "באופן קבוע, בזמנים רגועים", "approach": "Theraplay", "targets": ["t4"], "sentences": ["איפה הבובה? הנה היא!", "אני מתחבא/ת, תמצא/י אותי", "הבובה חזרה!"]}, {"id": "i4", "name": "לוח מתי חוזרים", "what": "תמונה של המבוגר על לוח היום, ליד הרגע שבו הוא חוזר: אחרי השינה, אחרי הארוחה.", "why": "כשרואים מתי חוזרים, ההמתנה קלה יותר.", "freq": "כל יום", "approach": "ARC", "targets": ["t5"], "sentences": ["בוא/י נראה מתי נתראה", "אחרי השינה אני כאן", "עוד שינה אחת"]}, {"id": "i5", "name": "פרידה מחבר שעוזב", "what": "כשילד עוזב את המרכז, עושים טקס קטן: ציור או מילה טובה. תמונה רק לפי נוהל המרכז לצילום ילדים.", "why": "פרידה מסודרת עוזרת להתמודד עם אובדן.", "freq": "כשילד עוזב", "approach": "ARC", "targets": ["t3"], "sentences": ["היום נפרדים מחבר", "רוצה לצייר לו משהו?", "מותר להיות עצוב/ה"], "avoid": "לא להסתיר את העזיבה כדי לא להעציב"}, {"id": "i6", "name": "שיר פרידה ושיר חזרה", "what": "שיר קצר וקבוע לפרידה ושיר לחזרה, עם תנועות.", "why": "שיר וקצב מוכרים מרגיעים את הגוף.", "freq": "בפרידות ובחזרות", "approach": "NMT", "targets": ["t1", "t2"], "sentences": ["נשיר את שיר הביי", "עכשיו שיר החזרה", "עוד פעם?"]}, {"id": "i7", "name": "חפץ קטן לשמור", "what": "בפרידה ארוכה, המבוגר משאיר לשמירה חפץ בטוח לגיל ולא קטן מדי, כמו צעיף או תמונה.", "why": "חפץ קטן מחזיק את הקשר בזמן ההיעדרות.", "freq": "בפרידות ארוכות", "approach": "מעגל הביטחון", "targets": ["t1", "t5"], "sentences": ["זה שלי, והוא נשאר איתך עד שאחזור", "כשאחזור, תחזיר/י לי אותו", "הוא מזכיר לך אותי"]}, {"id": "i8", "name": "מילים לרגש של פרידה", "what": "אומרים בקול את הרגש של הפרידה, ומקבלים בכי בלי למהר לעצור אותו.", "why": "רגש שמקבל שם נעשה פחות מפחיד.", "freq": "בפרידות", "approach": "DDP/PACE", "targets": ["t1", "t3"], "sentences": ["עצוב לך שאני הולך/ת", "זה בסדר לבכות", "נשב יחד עד שיהיה יותר טוב"], "avoid": "לא להגיד ''אל תבכה''"}]}}}'::jsonb, true) on conflict (scope, institution, kind, title) do update set description = excluded.description, themes = excluded.themes, category = excluded.category, methods = excluded.methods, content = excluded.content, active = true where mercury_library.draft;
insert into public.mercury_library (scope, kind, title, description, themes, category, methods, content, draft) values ('mercury', 'goal', 'חפץ מעבר וקשר עם מי שרחוק', 'להחזיק קשר עם המשפחה דרך חפץ, תמונה וזיכרון', array['אובדן ופרידה']::text[], 'אובדן ופרידה', array['מעגל הביטחון', 'ARC', 'טיפול נרטיבי', 'DDP/PACE', 'NMT']::text[], '{"v": 2, "bank": 3, "review": 3, "avoid": "לא להבטיח שיחה או ביקור שלא נקבעו", "strengths": ["אמון", "חום", "דמיון"], "skills": ["שמירת קשר"], "main": "2-5", "also": ["6-9"], "evidence": {"level": "derived", "note": "נגזר מתיאוריית ההתקשרות (חפץ מעבר) ומגישות נרטיביות לעבודה עם ילדים בהשמה. קופסת זיכרונות ותמונה ליד המיטה הן פרקטיקה מקובלת; כל קשר עם המשפחה נעשה לפי מה שנקבע בתוכנית ובתיאום עם המטפלת."}, "ages": {"2-5": {"targets": [{"id": "t1", "text": "כשיש חפץ מהבית או מהמשפחה, משתמש/ת בו כדי להירגע", "staff": "נרגע/ת עם החפץ שלו/ה", "scale": ["עדיין אין חפץ, או לא נוגע/ת בו", "מחזיק/ה בחפץ כשנותנים", "מחפש/ת את החפץ כשקשה", "נרגע/ת עם החפץ", "לוקח/ת את החפץ בעצמו/ה כשצריך"]}, {"id": "t2", "text": "כשיש הזדמנות, מדבר/ת או משחק/ת על המשפחה", "staff": "מדבר/ת על המשפחה שלו/ה", "scale": ["עדיין לא מזכיר/ה את המשפחה", "מזכיר/ה במשחק", "מראה תמונה כשמציעים", "מספר/ת משהו קטן", "מספר/ת ושואל/ת שאלות"]}, {"id": "t3", "text": "כשיש שיחה או ביקור לפי התוכנית, נפרד/ת בעזרת מבוגר וחוזר/ת ליום", "staff": "נרגע/ת אחרי שיחה או ביקור", "scale": ["עדיין מתקשה מאוד אחרי כל קשר", "נרגע/ת אחרי זמן רב", "נרגע/ת בעזרת מבוגר", "נרגע/ת מהר אחרי הקשר", "מחכה לקשר הבא ויודע/ת מתי"]}, {"id": "t4", "text": "שומר/ת זיכרונות במקום משלו/ה, כמו קופסה או אלבום", "staff": "שומר/ת זיכרונות בקופסה שלו/ה", "scale": ["עדיין אין מקום לזיכרונות", "מסתכל/ת כשמבוגר מראה", "שם/ה משהו בקופסה", "פותח/ת את הקופסה כשרוצה", "מראה את הקופסה למבוגר ומספר/ת"]}, {"id": "t5", "text": "מראה או אומר/ת כשמתגעגע/ת", "staff": "אומר/ת לנו כשמתגעגע/ת", "scale": ["עדיין לא מראה געגוע", "מראה בהתנהגות, בבכי או בכעס", "מצביע/ה על תמונה או על פרצוף", "אומר/ת שמתגעגע/ת", "אומר/ת, ומבקש/ת משהו שעוזר"]}], "interventions": [{"id": "i1", "name": "חפץ מהבית", "what": "מוודאים שיש חפץ מהבית או מהמשפחה, ושומרים עליו היטב.", "why": "חפץ מוכר נותן ביטחון ומחבר למי שרחוק.", "freq": "תמיד", "approach": "מעגל הביטחון", "targets": ["t1"], "sentences": ["הדובי שלך כאן, שמרנו עליו", "רוצה להחזיק אותו?", "הוא בא איתך לישון"], "avoid": "לא לקחת את החפץ כעונש"}, {"id": "i2", "name": "תמונה ליד המיטה", "what": "בתיאום עם המטפלת, תמונה של המשפחה ליד המיטה או בקופסה.", "why": "תמונה מזכירה שהקשר קיים גם כשרחוק.", "freq": "לפי החלטת המטפלת", "approach": "ARC", "targets": ["t2", "t5"], "sentences": ["רוצה לראות את התמונה?", "מי זה בתמונה?", "אפשר להגיד לתמונה לילה טוב"]}, {"id": "i3", "name": "קופסת זיכרונות", "what": "קופסה אישית לציורים, תמונות ופתקים, שהילד/ה מקשט/ת.", "why": "מקום לזיכרונות שומר על הסיפור של הילד/ה.", "freq": "באופן קבוע", "approach": "טיפול נרטיבי", "targets": ["t4"], "sentences": ["בוא/י נקשט את הקופסה שלך", "מה נשים בה היום?", "הקופסה שלך, ורק שלך"]}, {"id": "i4", "name": "הכנה וליווי סביב קשר", "what": "לפני שיחה או ביקור שנקבעו, מספרים מתי ומה יהיה. אחרי הקשר נשארים קרוב.", "why": "הכנה וליווי מקטינים את הסערה סביב הקשר.", "freq": "לפני ואחרי כל קשר", "approach": "ARC", "targets": ["t3"], "sentences": ["אחרי ארוחת הצהריים תדבר/י עם המשפחה", "אני אהיה לידך", "אחרי השיחה נשב יחד"]}, {"id": "i5", "name": "משחק על מי שרחוק", "what": "משחק בבובות שבו מישהו רחוק וחוזר, בהובלת הילד/ה. המבוגר משתתף ולא מפרש.", "why": "במשחק אפשר לבטא געגוע שעוד אין לו מילים.", "freq": "באופן קבוע", "approach": "DDP/PACE", "targets": ["t2", "t5"], "sentences": ["מה הבובה מרגישה?", "היא מתגעגעת?", "מה יעזור לה?"]}, {"id": "i6", "name": "ציור בשביל המשפחה", "what": "מציירים יחד בשביל אנשים שרחוקים. מה נשלח ומה נשמר בקופסה, מחליטה המטפלת.", "why": "כשמבטאים געגוע, קל יותר לשאת אותו.", "freq": "כשיש געגוע", "approach": "טיפול נרטיבי", "targets": ["t5", "t4"], "sentences": ["רוצה לצייר משהו בשבילם?", "מה נצייר?", "נשמור את זה בקופסה שלך"], "avoid": "לא להבטיח שהציור יישלח"}, {"id": "i7", "name": "מילים לגעגוע", "what": "כשרואים געגוע, נותנים לו שם ומקבלים אותו, בלי להסיח מהר.", "why": "געגוע שמקבל מקום קל יותר לשאת.", "freq": "כשיש געגוע", "approach": "DDP/PACE", "targets": ["t5"], "sentences": ["נראה לי שיש געגוע", "מותר להתגעגע", "אני כאן איתך"]}, {"id": "i8", "name": "טקס לילה עם החפץ", "what": "בטקס הערב מחבקים את החפץ, ואומרים משפט קבוע שסוכם עם המטפלת.", "why": "בלילה הגעגוע גדול, וטקס קבוע מרגיע.", "freq": "כל ערב", "approach": "NMT", "targets": ["t1", "t5"], "sentences": ["הדובי איתך, ואנחנו שומרים עליך", "אנחנו חושבים עליך", "לילה טוב, שומרים עליך כל הלילה"]}]}}}'::jsonb, true) on conflict (scope, institution, kind, title) do update set description = excluded.description, themes = excluded.themes, category = excluded.category, methods = excluded.methods, content = excluded.content, active = true where mercury_library.draft;
insert into public.mercury_library (scope, kind, title, description, themes, category, methods, content, draft) values ('mercury', 'goal', 'ביקורים עם המשפחה: לפני, בזמן, אחרי', 'להתכונן לביקור, להיות בו בביטחון, ולחזור לשגרה אחריו', array['אובדן ופרידה']::text[], 'אובדן ופרידה', array['ARC', 'TBRI', 'DDP/PACE', 'CPS', 'ויסות חושי', 'מעגל הביטחון']::text[], '{"v": 2, "bank": 3, "review": 1, "avoid": "לא לדבר רעה על המשפחה", "strengths": ["כנות", "גמישות", "עמידות"], "skills": ["התמודדות עם ביקורים"], "main": "6-9", "also": ["10-12"], "evidence": {"level": "derived", "note": "נשען על ARC ועל הספרות על מפגשי ילדים בהשמה עם המשפחה, שממליצה על הכנה וליווי, בעיקר מניסיון קליני. הפעולות כאן הן התאמה יישומית לשגרת הצוות, וכל ביקור מתקיים לפי מה שנקבע בתוכנית."}, "ages": {"6-9": {"targets": [{"id": "t1", "text": "לפני ביקור, יודע/ת מתי הוא ומה יהיה בו", "staff": "יודע/ת מתי הביקור ומה יהיה", "scale": ["עדיין לא יודע/ת, ומתוח/ה", "שואל/ת שוב ושוב", "יודע/ת מתי, בעזרת הלוח", "יודע/ת מתי ומה יהיה", "מתכונן/ת בעצמו/ה לביקור"]}, {"id": "t2", "text": "בזמן הביקור, פונה למבוגר המלווה כשצריך", "staff": "פונה למלווה בביקור כשצריך", "scale": ["עדיין לא פונה בביקור", "פונה רק כשקשה מאוד", "פונה כשהמלווה שואל", "פונה בעצמו/ה כשצריך", "פונה ויודע/ת מתי לבקש הפסקה"]}, {"id": "t3", "text": "אחרי הביקור, חוזר/ת לשגרה תוך זמן קצר", "staff": "חוזר/ת לשגרה אחרי ביקור", "scale": ["עדיין סוער/ת ימים אחרי ביקור", "סוער/ת יום שלם", "נרגע/ת אחרי כמה שעות", "נרגע/ת מהר עם מבוגר", "חוזר/ת לשגרה בעצמו/ה"]}, {"id": "t4", "text": "כשיש הזדמנות, משתף/ת מבוגר ברגשות אחרי הביקור", "staff": "מספר/ת לנו איך היה", "scale": ["עדיין לא מדבר/ת על הביקור", "מראה רגש בהתנהגות", "מספר/ת עובדות", "מספר/ת גם מה הרגיש/ה", "מספר/ת ושואל/ת מה הלאה"]}, {"id": "t5", "text": "כשביקור מתבטל או משתנה, מתמודד/ת בעזרת מבוגר", "staff": "מתמודד/ת כשביקור מתבטל", "scale": ["עדיין מתפרץ/ת או מתנתק/ת", "נרגע/ת אחרי זמן רב", "נרגע/ת בעזרת מבוגר", "מדבר/ת על האכזבה", "מבין/ה ויודע/ת מה עכשיו"]}], "interventions": [{"id": "i1", "name": "הכנה לפני ביקור", "what": "יום או יומיים לפני, מסבירים מתי, איפה, מי יהיה ומי מלווה, ומסמנים בלוח.", "why": "ידיעה מראש מורידה מתח.", "freq": "לפני כל ביקור", "approach": "ARC", "targets": ["t1"], "sentences": ["ביום רביעי יש ביקור, נסמן בלוח", "נראה יחד מי מלווה אותך", "מה חשוב לך לספר להם?"]}, {"id": "i2", "name": "תוכנית קטנה לביקור", "what": "מסכמים יחד מה עושים בביקור, כמו משחק או ציור, ומה הסימן למלווה כשקשה.", "why": "תוכנית נותנת תחושת שליטה ברגע טעון.", "freq": "לפני כל ביקור", "approach": "CPS", "targets": ["t2"], "sentences": ["מה נביא לביקור?", "מה הסימן שלך אם צריך הפסקה?", "אני אבין את הסימן"]}, {"id": "i3", "name": "מלווה רגוע", "what": "המלווה נשאר בקרבת מקום, רגוע ולא שופט, ומתערב רק כשצריך.", "why": "נוכחות רגועה מאפשרת להיות בביקור בביטחון.", "freq": "בכל ביקור", "approach": "TBRI", "targets": ["t2"], "sentences": ["אני כאן אם צריך", "רוצה הפסקה קטנה?", "אפשר להמשיך כשמוכן/ה"]}, {"id": "i4", "name": "נחיתה רכה אחרי", "what": "אחרי הביקור זמן שקט: אוכל, מקלחת, משחק רגוע, ומעט דרישות.", "why": "הגוף צריך זמן להירגע אחרי סערת רגשות.", "freq": "אחרי כל ביקור", "approach": "ויסות חושי", "targets": ["t3"], "sentences": ["עכשיו זמן שקט, בלי למהר", "רוצה לאכול משהו?", "אפשר לנוח קצת, בלי לדבר"]}, {"id": "i5", "name": "שיחה פתוחה אחרי", "what": "מזמינים לספר, ומקבלים כל רגש: שמחה, כעס, עצב או בלבול.", "why": "כל הרגשות מותרים, גם כשהם מעורבים.", "freq": "אחרי ביקור, כשמוכן/ה", "approach": "DDP/PACE", "targets": ["t4"], "sentences": ["איך היה לך?", "הגיוני להרגיש גם שמח וגם עצוב", "תודה שסיפרת"], "avoid": "לא לחקור. אם הילד/ה מספר/ת משהו מדאיג מהביקור, מקשיבים ומעבירים מיד למטפלת"}, {"id": "i6", "name": "כשביקור מתבטל", "what": "אומרים בכנות ובפשטות, נשארים קרוב, ומתכננים משהו טוב לזמן הזה.", "why": "אכזבה עם מבוגר לצד קלה יותר לשאת.", "freq": "כשביקור מתבטל", "approach": "ARC", "targets": ["t5"], "sentences": ["הביקור לא יתקיים היום, ואני מצטער/ת", "איך זה בשבילך? כל רגש מותר", "בוא/י נעשה משהו יחד עכשיו"], "avoid": "לא להאשים את המשפחה מול הילד/ה"}, {"id": "i7", "name": "מספרים למטפלת", "what": "מתעדים בקצרה איך היה לפני הביקור, בזמנו ואחריו, ומעבירים למטפלת.", "why": "תמונה מלאה עוזרת להתאים את הביקורים הבאים.", "freq": "אחרי כל ביקור", "approach": "ARC", "targets": ["t3", "t4"], "sentences": ["אני מספר/ת למטפלת איך היה, כדי שתעזור", "מה חשוב שהיא תדע?", "אנחנו צוות אחד בשבילך"]}, {"id": "i8", "name": "חפץ גשר", "what": "באישור המטפלת, הילד/ה לוקח/ת לביקור חפץ מוכר מהמרכז. מה שחוזר מהביקור עובר דרך המלווה, לפי נוהל המרכז.", "why": "חפץ מגשר בין שני המקומות.", "freq": "בביקורים", "approach": "מעגל הביטחון", "targets": ["t2", "t3"], "sentences": ["רוצה לקחת את הדובי לביקור?", "מה הבאת מהביקור?", "נשים את זה בקופסה שלך"]}]}}}'::jsonb, true) on conflict (scope, institution, kind, title) do update set description = excluded.description, themes = excluded.themes, category = excluded.category, methods = excluded.methods, content = excluded.content, active = true where mercury_library.draft;
insert into public.mercury_library (scope, kind, title, description, themes, category, methods, content, draft) values ('mercury', 'goal', 'מקום לגעגוע ולעצב', 'להתגעגע, להיות עצוב/ה ולקבל נחמה', array['אובדן ופרידה']::text[], 'אובדן ופרידה', array['טיפול נרטיבי', 'DDP/PACE', 'ARC', 'ויסות חושי']::text[], '{"v": 2, "bank": 3, "review": 3, "avoid": "לא למהר לעודד או להסיח כשעצוב", "strengths": ["רגישות", "כנות", "יצירתיות"], "skills": ["ביטוי רגשות"], "main": "6-9", "also": ["10-12"], "evidence": {"level": "derived", "note": "נשען על עבודת אבל עם ילדים, על הגישה הנרטיבית ועל רכיבי האבל של TF-CBT. זמן געגוע קבוע וקופסת זיכרונות טובים הם התאמה יישומית לשגרת הצוות, שטרם נבדקה."}, "ages": {"6-9": {"targets": [{"id": "t1", "text": "כשיש הזדמנות, אומר/ת שמתגעגע/ת או שעצוב לו/ה", "staff": "אומר/ת לנו כשעצוב לו/ה", "scale": ["עדיין לא מראה עצב", "מראה עצב בהתנהגות", "אומר/ת כששואלים", "אומר/ת בעצמו/ה לפעמים", "אומר/ת, ומבקש/ת מה שעוזר"]}, {"id": "t2", "text": "מבטא/ת געגוע בדרך יצירתית: ציור, מכתב או משחק", "staff": "מצייר/ת או כותב/ת כשמתגעגע/ת", "scale": ["עדיין לא מבטא/ת", "מבטא/ת כשמבוגר מזמין", "מבטא/ת בדרך אחת", "בוחר/ת דרך בעצמו/ה", "משתף/ת מבוגר במה שיצר/ה"]}, {"id": "t3", "text": "מקבל/ת נחמה ממבוגר כשעצוב לו/ה", "staff": "מסכים/ה שנשב לידו/ה כשעצוב", "scale": ["עדיין מסתגר/ת לבד", "מקבל/ת נחמה אחרי זמן", "מקבל/ת נחמה ממבוגר מוכר", "מבקש/ת נחמה בעצמו/ה", "מבקש/ת נחמה ממבוגרים שונים"]}, {"id": "t4", "text": "אחרי רגע עצוב, חוזר/ת לפעילות", "staff": "ממשיך/ה את היום אחרי רגע עצוב", "scale": ["עדיין העצב עוצר את כל היום", "חוזר/ת אחרי זמן רב", "חוזר/ת בעזרת מבוגר", "חוזר/ת אחרי זמן קצר", "חוזר/ת ויודע/ת מה עזר"]}, {"id": "t5", "text": "מזכיר/ה רגעים טובים עם מי שרחוק", "staff": "מספר/ת זיכרונות טובים", "scale": ["עדיין לא מזכיר/ה", "מזכיר/ה כשמראים תמונה", "מספר/ת זיכרון אחד", "מספר/ת כמה זיכרונות", "מספר/ת זיכרונות טובים וגם קשים"]}], "interventions": [{"id": "i1", "name": "מקבלים את העצב", "what": "כשעצוב, אומרים בקול מה רואים ומקבלים, בלי לנסות לתקן מהר.", "why": "עצב שמקבל מקום עובר טוב יותר.", "freq": "ברגעי עצב", "approach": "DDP/PACE", "targets": ["t1", "t3"], "sentences": ["נראה שעצוב לך", "מותר להתגעגע", "אני יושב/ת איתך"], "avoid": "לא להגיד ''אל תהיה עצוב''"}, {"id": "i2", "name": "זמן געגוע", "what": "זמן קבוע ושקט לדבר, לצייר או להסתכל בתמונות של מי שרחוק. תמונות של המשפחה, בתיאום עם המטפלת.", "why": "מקום קבוע לגעגוע מפחית הצפות לא צפויות.", "freq": "באופן קבוע", "approach": "טיפול נרטיבי", "targets": ["t2", "t5"], "sentences": ["עכשיו זמן לחשוב על מי שרחוק", "על מי בא לך לדבר היום?", "רוצה לצייר משהו?"]}, {"id": "i3", "name": "מכתב שלא חייב להישלח", "what": "כותבים או מציירים לאדם שמתגעגעים אליו. מה נשלח, מחליטה המטפלת.", "why": "מילים על נייר מקלות על הלב.", "freq": "כשיש געגוע", "approach": "טיפול נרטיבי", "targets": ["t2"], "sentences": ["מה היית רוצה להגיד?", "אפשר לכתוב או לצייר", "נשמור את זה בקופסה"], "avoid": "לא להבטיח שהמכתב יישלח"}, {"id": "i4", "name": "נחמה בגוף", "what": "שמיכה רכה, שתייה חמה, חיבוק בהסכמה, או ישיבה קרובה.", "why": "נחמה בגוף מרגיעה כשקשה למצוא מילים.", "freq": "ברגעי עצב", "approach": "ויסות חושי", "targets": ["t3"], "sentences": ["רוצה שמיכה?", "נשתה משהו חם ביחד", "אפשר לשבת קרוב"]}, {"id": "i5", "name": "ספר על געגוע", "what": "קוראים יחד ספר ילדים על געגוע ופרידה, ומדברים על הדמויות.", "why": "דרך דמות קל יותר לדבר על עצמי.", "freq": "מדי פעם", "approach": "טיפול נרטיבי", "targets": ["t1", "t5"], "sentences": ["גם הדמות מתגעגעת, כמוך?", "מה עזר לה?", "מה עוזר לך?"]}, {"id": "i6", "name": "חזרה עדינה ליום", "what": "אחרי שהעצב קיבל מקום, מציעים פעילות נעימה, בלי לבטל את מה שהיה.", "why": "חזרה עדינה מראה שהעצב לא עוצר את כל היום.", "freq": "אחרי רגע עצוב", "approach": "ARC", "targets": ["t4"], "sentences": ["רוצה שנשחק משהו עכשיו?", "אפשר להיות עצוב/ה וגם לשחק", "אפשר לחזור לדבר על זה מתי שרוצים"]}, {"id": "i7", "name": "זיכרונות טובים לקופסה", "what": "מוסיפים לקופסת הזיכרונות זיכרונות טובים: תמונה, סיפור או שיר.", "why": "זיכרונות טובים הם חלק מהסיפור, גם כשיש עצב.", "freq": "באופן קבוע", "approach": "טיפול נרטיבי", "targets": ["t5"], "sentences": ["מה זיכרון טוב שיש לך?", "נכתוב אותו לקופסה", "איזה שיר מזכיר לך אותם?"]}, {"id": "i8", "name": "מעדכנים את המטפלת", "what": "כשהעצב חזק או נמשך כמה ימים, מעדכנים את המטפלת. אם הילד/ה מדבר/ת על מוות, על רצון להיעלם או על פגיעה בעצמו/ה, מעדכנים מיד את האחראי במשמרת ואת המטפלת.", "why": "עצב ממושך צריך ליווי טיפולי.", "freq": "כשהעצב חזק או ממושך", "approach": "ARC", "targets": ["t1", "t4"], "sentences": ["אני רואה שקשה לך כבר כמה ימים", "נספר למטפלת, כדי שתעזור", "אנחנו כאן בשבילך"]}]}}}'::jsonb, true) on conflict (scope, institution, kind, title) do update set description = excluded.description, themes = excluded.themes, category = excluded.category, methods = excluded.methods, content = excluded.content, active = true where mercury_library.draft;
insert into public.mercury_library (scope, kind, title, description, themes, category, methods, content, draft) values ('mercury', 'goal', 'הסיפור שלי: למה אני כאן', 'להבין במילים פשוטות ואמיתיות למה הגעתי, ושזו לא אשמתי', array['אובדן ופרידה']::text[], 'אובדן ופרידה', array['טיפול נרטיבי', 'TF-CBT', 'DDP/PACE', 'ARC', 'CPS']::text[], '{"v": 2, "bank": 3, "review": 3, "avoid": "לא לספר פרטים על המשפחה מעבר למה שהמטפלת קבעה", "strengths": ["כנות", "אומץ", "סקרנות", "מודעות עצמית"], "skills": ["הבנת הסיפור האישי"], "main": "10-12", "also": ["13-15"], "evidence": {"level": "derived", "note": "נשען על עבודת סיפור חיים (Life Story Work), על הגישה הנרטיבית ועל TF-CBT, שבו נבנה הסיפור בהנחיית מטפל. תפקיד הצוות כאן הוא תמיכה ועקביות, ולא בניית הסיפור עצמו."}, "ages": {"10-12": {"targets": [{"id": "t1", "text": "כשיש הזדמנות, שואל/ת שאלות על הסיבה שהוא/היא כאן", "staff": "שואל/ת למה הוא/היא כאן", "scale": ["עדיין לא שואל/ת, ושומר/ת בפנים", "שואל/ת בעקיפין או בכעס", "שואל/ת מבוגר מוכר", "שואל/ת ומקשיב/ה לתשובה", "שואל/ת ומבקש/ת לדבר עם המטפלת"]}, {"id": "t2", "text": "מספר/ת במילים פשוטות למה הוא/היא במרכז, לפי הנוסח שסוכם עם המטפלת", "staff": "מספר/ת במילים שלו/ה למה הוא/היא כאן", "scale": ["עדיין לא יודע/ת, או מסביר/ה לעצמו/ה בדרך אחרת", "יודע/ת חלק קטן", "מספר/ת כששואלים", "מספר/ת במילים שלו/ה", "מספר/ת, וגם מה עוזר עכשיו"]}, {"id": "t3", "text": "אומר/ת שמה שקרה הוא לא באשמתו/ה (בהנחיית המטפלת)", "staff": "אומר/ת שזו לא אשמתו/ה", "scale": ["עדיין מאשים/ה את עצמו/ה", "מקשיב/ה כשאומרים שזו לא אשמתו/ה", "חוזר/ת על המשפט כשמזכירים", "אומר/ת את זה בעצמו/ה לפעמים", "מאמין/ה בזה ומרגיש/ה הקלה"]}, {"id": "t4", "text": "משתתף/ת בבניית ספר חיים או ציר זמן עם המטפלת", "staff": "בונה עם המטפלת את הספר שלו/ה", "scale": ["עדיין לא מוכן/ה", "מסתכל/ת על הספר", "מוסיף/ה דבר אחד", "מוסיף/ה כמה דברים ומספר/ת", "מראה את הספר למבוגר שבוחר/ת"]}, {"id": "t5", "text": "מבחין/ה בין מה שקרה לו/ה לבין מי שהוא/היא: חוזקות, תחביבים וחלומות", "staff": "מספר/ת גם מה טוב בו/ה", "scale": ["עדיין רואה בעצמו/ה רק את מה שקרה", "מזכיר/ה דבר טוב כששואלים", "מספר/ת על חוזקה אחת", "מספר/ת על כמה חוזקות", "מדבר/ת גם על העתיד שלו/ה"]}], "interventions": [{"id": "i1", "name": "נוסח מוסכם", "what": "המטפלת מנסחת משפט קצר ואמיתי על הסיבה להגעה, וכל הצוות עונה באותן מילים.", "why": "תשובה זהה מכל מבוגר בונה אמון ומונעת בלבול.", "freq": "בכל שאלה", "approach": "ARC", "targets": ["t1", "t2"], "sentences": ["זו שאלה חשובה", "אני אגיד לך מה שסיכמנו עם המטפלת", "את השאר אפשר לשאול אותה"], "avoid": "לא לענות בניחוש או בפרטים שלא סוכמו"}, {"id": "i2", "name": "זו לא אשמתך (בהנחיית המטפלת)", "what": "המשפט נאמר בניסוח שהמטפלת קבעה, ברגעים שהיא ממליצה עליהם.", "why": "ילדים רבים מאשימים את עצמם במה שקרה.", "freq": "לפי הנחיית המטפלת", "approach": "TF-CBT", "targets": ["t3"], "sentences": ["מה שקרה זו לא אשמתך", "ילדים לא אחראים להחלטות של מבוגרים", "מותר להרגיש כל מה שמרגישים"], "avoid": "לא לומר בלי תיאום, ולא להתווכח כשמאשים/ה את עצמו/ה"}, {"id": "i3", "name": "ספר חיים (בהנחיית המטפלת)", "what": "המטפלת בונה עם הילד/ה ספר: תמונות, אנשים, מקומות ומה קרה. הצוות עוזר לאסוף תמונות וזיכרונות מהמרכז.", "why": "סיפור מסודר עוזר להבין את מה שקרה.", "freq": "לפי הנחיית המטפלת", "approach": "טיפול נרטיבי", "targets": ["t4"], "sentences": ["נצלם תמונה לספר שלך?", "מה חשוב לשים בספר מכאן?", "זה הספר שלך, ורק מה שתבחר/י ייכנס"]}, {"id": "i4", "name": "מקשיבים בלי לחקור", "what": "כשמספר/ת על העבר, מקשיבים בסקרנות, לא חוקרים, ומעבירים למטפלת.", "why": "הקשבה רגועה מראה שבטוח לספר.", "freq": "כשהילד/ה משתף/ת", "approach": "DDP/PACE", "targets": ["t1", "t2"], "sentences": ["תודה שסיפרת לי", "זה נשמע קשה מאוד", "חשוב שגם המטפלת תדע, כדי שתוכל לעזור"], "avoid": "לא לשאול שאלות חוקרות על מה שקרה"}, {"id": "i5", "name": "מי אני, חוץ ממה שקרה", "what": "מדברים על חוזקות, תחביבים וחלומות, ומכניסים גם אותם לספר.", "why": "סיפור החיים כולל גם חוזקות ותקוות.", "freq": "באופן קבוע", "approach": "טיפול נרטיבי", "targets": ["t5"], "sentences": ["ספר/י לי על משהו שכיף לך לעשות", "ראיתי כמה עזרת היום לחבר", "מה החלום שלך?"]}, {"id": "i6", "name": "שאלות בכתב", "what": "תיבה או מחברת לשאלות שקשה לשאול בקול, והמטפלת עונה בפגישה.", "why": "שאלה בכתב קלה יותר משאלה בקול.", "freq": "תמיד זמין", "approach": "CPS", "targets": ["t1"], "sentences": ["אפשר לכתוב כל שאלה", "המטפלת תענה בפגישה", "אין שאלה טיפשית"]}, {"id": "i7", "name": "ימים שמעוררים את הסיפור", "what": "בימים טעונים, כמו יום הולדת, חג או תאריך ההגעה, מתכוננים מראש ונשארים קרוב.", "why": "ימים מסוימים מעוררים את הסיפור מחדש.", "freq": "לפני ימים טעונים", "approach": "ARC", "targets": ["t1", "t3"], "sentences": ["מחר יום מיוחד, ואולי יהיה מורכב", "מה יעזור שיהיה יותר קל?", "אני כאן גם מחר"]}, {"id": "i8", "name": "בפרטיות, לא מול הקבוצה", "what": "על שאלות על הסיפור עונים בפרטיות, לא מול ילדים אחרים.", "why": "פרטיות שומרת על כבוד ומונעת בושה.", "freq": "בכל שאלה רגישה", "approach": "DDP/PACE", "targets": ["t1", "t2"], "sentences": ["בוא/י נדבר על זה רגע בצד", "זה שלך, ולא של כולם", "נמשיך את זה בשקט"]}]}}}'::jsonb, true) on conflict (scope, institution, kind, title) do update set description = excluded.description, themes = excluded.themes, category = excluded.category, methods = excluded.methods, content = excluded.content, active = true where mercury_library.draft;
insert into public.mercury_library (scope, kind, title, description, themes, category, methods, content, draft) values ('mercury', 'goal', 'קשר עם המשפחה: רגשות מורכבים וגבולות', 'להחזיק אהבה, כעס ודאגה כלפי המשפחה, ולשמור על עצמי בקשר', array['אובדן ופרידה']::text[], 'אובדן ופרידה', array['DDP/PACE', 'טיפול נרטיבי', 'CPS', 'ARC']::text[], '{"v": 2, "bank": 3, "review": 3, "avoid": "לא לבקש לבחור צד בין המשפחה לבין המרכז", "strengths": ["כנות", "בגרות", "עמידות", "אחריות"], "skills": ["החזקת רגשות מעורבים"], "main": "13-15", "also": [], "evidence": {"level": "derived", "note": "נשען על DDP/PACE, על הגישה הנרטיבית ועל TF-CBT. הראיות למתבגרים בהשמה מוגבלות; העקרונות של קבלת רגשות מעורבים, עקביות בכללי הקשר והימנעות מבחירת צד מקובלים בספרות המקצועית."}, "ages": {"13-15": {"targets": [{"id": "t1", "text": "כשיש הזדמנות, מדבר/ת עם מבוגר על רגשות מעורבים כלפי המשפחה: אהבה, כעס ודאגה", "staff": "מדבר/ת איתנו על רגשות כלפי המשפחה", "scale": ["עדיין נמנע/ת מהנושא", "מדבר/ת רק על עובדות", "מדבר/ת על רגש אחד", "מדבר/ת על רגשות מעורבים", "מבין/ה שאפשר להרגיש כמה דברים יחד"]}, {"id": "t2", "text": "שומר/ת על כללי הקשר עם המשפחה, לפי מה שנקבע בתוכנית", "staff": "שומר/ת על מה שסוכם בקשר עם המשפחה", "scale": ["עדיין חורג/ת מהמוסכם", "שומר/ת עם תזכורות רבות", "שומר/ת ברוב הפעמים", "שומר/ת, ומספר/ת כשקשה", "מבין/ה את הסיבות ושותף/ה לתוכנית"]}, {"id": "t3", "text": "כשמשהו בקשר עם המשפחה מכאיב, מספר/ת למבוגר", "staff": "מספר/ת לנו כשהקשר עם המשפחה מכאיב", "scale": ["עדיין שומר/ת בפנים או מתפרץ/ת", "מראה בהתנהגות", "מספר/ת כששואלים", "מספר/ת בעצמו/ה", "מספר/ת ומבקש/ת עזרה בצעד הבא"]}, {"id": "t4", "text": "מזהה כשמשהו בקשר פוגע, ופונה למבוגר כדי לעצור או לסיים את השיחה", "staff": "פונה אלינו כששיחה עם המשפחה פוגעת", "scale": ["עדיין לא מזהה כשהקשר פוגע", "מזהה כשמשהו פוגע", "מתייעץ/ת עם מבוגר מה לעשות", "עוצר/ת שיחה פוגעת בעזרת מבוגר", "מציב/ה גבול בעצמו/ה, בכבוד, ופונה כשצריך"]}, {"id": "t5", "text": "חושב/ת על העתיד ועל הקשר שרוצה עם המשפחה", "staff": "מדבר/ת איתנו על הקשר העתידי עם המשפחה", "scale": ["עדיין לא חושב/ת על העתיד", "מזכיר/ה את העתיד בכעס או בייאוש", "מדבר/ת על משאלה אחת", "מדבר/ת על כמה אפשרויות", "מתכנן/ת צעדים עם המטפלת"]}], "interventions": [{"id": "i1", "name": "מקום לרגשות מעורבים", "what": "מקבלים גם אהבה וגם כעס כלפי המשפחה, בלי לתקן ובלי לשפוט.", "why": "כשמותר לדבר על רגשות מעורבים, הם מציפים פחות.", "freq": "בכל שיחה על המשפחה", "approach": "DDP/PACE", "targets": ["t1"], "sentences": ["אפשר לאהוב ולכעוס באותו זמן", "הגיוני שזה מבלבל", "מה הכי קשה לך בזה?"], "avoid": "לא לבקר את המשפחה וגם לא להגן עליה. משקפים את מה שהנער/ה מרגיש/ה"}, {"id": "i2", "name": "כללי קשר ברורים", "what": "המטפלת מסבירה מה נקבע לגבי שיחות וביקורים, והצוות שומר על זה באופן עקבי.", "why": "כללים ברורים ועקביים מקטינים מאבקים.", "freq": "באופן קבוע", "approach": "CPS", "targets": ["t2"], "sentences": ["זה מה שנקבע לגבי השיחות", "אם משהו לא מסתדר, נדבר עם המטפלת", "אני מבין/ה שזה מתסכל"]}, {"id": "i3", "name": "שיחה אחרי קשר", "what": "אחרי שיחה או ביקור, מזמינים לשיחה קצרה בפרטיות, בלי לחקור.", "why": "כשמדברים מיד, הרגשות לא מצטברים.", "freq": "אחרי שיחות וביקורים", "approach": "DDP/PACE", "targets": ["t3"], "sentences": ["איך היה?", "אם בא לך לדבר, אני כאן", "לא חייבים עכשיו"], "avoid": "לא לחקור מה נאמר בשיחה"}, {"id": "i4", "name": "מתרגלים גבולות", "what": "בזמן רגוע מתרגלים יחד איך מסיימים שיחה שפוגעת או מבקשים הפסקה, במילים מכבדות. המבוגר המלווה עוזר לעצור שיחה פוגעת.", "why": "גבול שומר גם על הנער/ה וגם על הקשר.", "freq": "באופן קבוע, בזמן רגוע", "approach": "CPS", "targets": ["t4"], "sentences": ["מה אפשר להגיד כשהשיחה פוגעת?", "מותר לסיים שיחה ולחזור אליה אחר כך", "איך הרגשת אחרי שהצבת גבול?"]}, {"id": "i5", "name": "מחברת אישית", "what": "מציעים מחברת אישית לכתוב בה מחשבות על המשפחה, שאף אחד לא קורא בלי רשות.", "why": "כתיבה מסדרת רגשות מבולבלים.", "freq": "תמיד זמין", "approach": "טיפול נרטיבי", "targets": ["t1", "t3"], "sentences": ["המחברת שלך, ואף אחד לא קורא בלי רשות", "לפעמים כתיבה מסדרת את הראש", "אם בא לך לשתף, אני כאן"]}, {"id": "i6", "name": "ימים משפחתיים", "what": "בימי הולדת, חגים ותאריכים משפחתיים מתכוננים מראש ונשארים קרובים.", "why": "ימים משפחתיים מעוררים געגוע וכאב.", "freq": "לפני ימים טעונים", "approach": "ARC", "targets": ["t3", "t1"], "sentences": ["החג מתקרב, איך זה בשבילך?", "מה יעזור ביום הזה?", "אני בודק/ת איתך מחר"]}, {"id": "i7", "name": "מדברים על העתיד", "what": "בשיחות קטנות מדברים על משאלות לעתיד ועל צעדים קטנים. את ההחלטות הגדולות מקבלים הגורמים המוסמכים, והמטפלת מעדכנת.", "why": "תקווה וחשיבה על העתיד מחזקות עמידות.", "freq": "מדי פעם", "approach": "טיפול נרטיבי", "targets": ["t5"], "sentences": ["איך היית רוצה שהקשר ייראה בעוד שנה?", "מה צעד קטן שאפשר לעשות?", "את ההחלטות הגדולות מקבלים הגורמים המוסמכים, והמטפלת תעדכן אותך"], "avoid": "לא להבטיח איך ייגמר ההליך"}, {"id": "i8", "name": "לא צריך לבחור צד", "what": "אומרים בבירור שמותר להרגיש טוב במרכז ובאותו זמן לאהוב את המשפחה.", "why": "אין צורך לבחור בין המשפחה לבין המרכז.", "freq": "כשהנושא עולה", "approach": "DDP/PACE", "targets": ["t1", "t2"], "sentences": ["מותר לך ליהנות כאן וגם לאהוב את המשפחה", "אף אחד לא מבקש ממך לבחור", "שני הדברים יכולים להיות נכונים"], "avoid": "לא לדבר על המרכז כעל בית טוב יותר"}]}}}'::jsonb, true) on conflict (scope, institution, kind, title) do update set description = excluded.description, themes = excluded.themes, category = excluded.category, methods = excluded.methods, content = excluded.content, active = true where mercury_library.draft;
