-- the goals of the first bank (bank2) leave the list: kept in the library, not offered any more
update public.mercury_library set active = false where scope = 'mercury' and kind = 'goal' and content ->> 'v' = '2' and coalesce(content ->> 'bank', '') <> '3';

select 'scheduling_v47_bank' as part, 'ok' as result, (select count(*) from public.mercury_library where kind = 'goal' and content ->> 'bank' = '3' and active) as goals_v3;
